window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[57]={"id":"057","numero":57,"titre":"Maltraitance et enfants en danger · PMI","objectifs":[{"id":"57-1","rang":"A","rubrique":"Définition","titre":"Nourrisson : connaître la définition du syndrome du bébé secoué","contenu":"<p>Le <span class=\"kw-etio\">syndrome du bébé secoué (SBS)</span> est un <strong>sous-ensemble des traumatismes crâniens infligés</strong> dans lequel c’est le <em>secouement</em>, seul ou associé à un impact, qui provoque le traumatisme crânien.</p>\n\n      <table >\n        <thead><tr><th>Item</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Cinétique</strong></td><td>Traumatisme « à <span class=\"kw-alerte\">haute cinétique</span> », comparable dans sa violence à un <strong>AVP</strong></td></tr>\n          <tr><td><strong><span class=\"kw-def\">Terrain</span></strong></td><td>Survient la plupart du temps chez un <span class=\"kw-clinique\">nourrisson de &lt; 1 an</span></td></tr>\n          <tr><td><strong><span class=\"kw-def\">Incidence</span></strong></td><td>Environ <strong>200 enfants/an</strong> en France</td></tr>\n          <tr><td><strong>Mécanisme</strong></td><td>Secousses <strong>toujours violentes</strong>, produites par : saisie manuelle du thorax sous <span class=\"kw-clinique\">les</span> aisselles ; saisie des 2 bras avec mouvements violents</td></tr>\n          <tr><td><strong>Morbi-<span class=\"kw-def\">mortalité</span></strong></td><td>\n            <ul>\n              <li><strong><span class=\"kw-def\">Mortalité</span> initiale :</strong> <span class=\"kw-alerte\">10 à 40 %</span> selon <span class=\"kw-clinique\">les</span> publications</li>\n              <li><strong>Séquelles :</strong> fréquentes et graves (cognitives, comportementales…)</li>\n            </ul>\n          </td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Suspicion de SBS = <span class=\"kw-alerte\">hospitalisation</span> en <span class=\"kw-alerte\">urgence</span>.</strong> Toute suspicion de SBS justifie une <span class=\"kw-alerte\">hospitalisation en urgence</span> 🏥 et un bilan paraclinique complet (<span class=\"kw-imagerie\">TDM</span> cérébrale, <span class=\"kw-imagerie\">IRM</span>, <span class=\"kw-imagerie\">FO</span>, RX squelette, <span class=\"kw-imagerie\">échographie</span> abdo, <span class=\"kw-imagerie\">EEG</span>).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 32 — Evaluation du nouveau-né · 47 — <span class=\"kw-def\">Suivi</span> d'un nourrisson, d'un enfant, d'un adolescent</em></p>","frequence":0},{"id":"57-2","rang":"B","rubrique":"Épidémiologie","titre":"Nourrisson : connaître les facteurs de risque de secousse","contenu":"<p><span class=\"kw-clinique\">Les</span> FR de secousse recoupent les FR généraux de maltraitance, avec une <strong>spécificité « nourrisson hurleur »</strong> : les pleurs prolongés inconsolables sont le déclencheur le plus fréquent du geste de secouement.</p>\n\n      <table >\n        <thead><tr><th>Axe</th><th><span class=\"kw-def\">Facteurs de risque</span></th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Liés à l’enfant</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Pleurs prolongés, inconsolables</span> (déclencheur principal du geste)</li>\n                <li>Âge <strong>&lt;<span class=\"kw-chiffre\"> 4 ans</span></strong>, pic d’<span class=\"kw-def\">incidence</span> &lt;<span class=\"kw-chiffre\"> 1 an</span></li>\n                <li>Enfant <strong>non désiré</strong> ou qui ne répond pas aux attentes des parents</li>\n                <li>Vulnérabilité : <span class=\"kw-clinique\">prématurité</span>, maladie chronique, handicap, troubles du comportement ou du développement</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Liés au parent / aidant</strong></td>\n            <td>\n              <ul>\n                <li>Difficulté à établir un lien avec le nouveau-né : séparation néonatale, <span class=\"kw-clinique\">dépression du post-partum</span></li>\n                <li>ATCD de maltraitances dans l’enfance</li>\n                <li>Manque de connaissances sur le développement de l’enfant, attentes irréalistes</li>\n                <li><span class=\"kw-alerte\">Addictions</span> (<span class=\"kw-etio\">alcool</span>, drogues, écrans), implication dans des activités criminelles</li>\n                <li>Difficultés financières, inoccupation, deuil, ATCD de MIN</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Relationnels</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-alerte\">Violences conjugales</span> au sein du foyer ⭐</li>\n                <li>Troubles physiques / psychiques ou problèmes de développement chez un membre de la famille</li>\n                <li>Éclatement de la cellule familiale, <span class=\"kw-def\">isolement</span>, absence de soutien familial élargi</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Communautaires / sociétaux</strong></td>\n            <td>\n              <ul>\n                <li>Inégalités sexuelles ou sociales, chômage élevé, pauvreté, manque de logements</li>\n                <li>Facilité d’accès à l’<span class=\"kw-etio\">alcool</span> et aux drogues</li>\n                <li>Normes culturelles glorifiant la violence ou <span class=\"kw-clinique\">les</span> châtiments corporels</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong><span class=\"kw-def\">Prévention primaire</span> — entretien du 4ᵉ mois de <span class=\"kw-ci\">grossesse</span>.</strong> L’<em>entretien médico-social du 4ᵉ mois</em> et <span class=\"kw-clinique\">les</span> campagnes de prévention des secousses (information sur les pleurs du nourrisson, accompagnement à la parentalité) sont les outils-clés de prévention du SBS.\n      </div>","frequence":0},{"id":"57-3","rang":"B","rubrique":"Physiopathologie","titre":"Nourrisson : connaître le mécanisme des lésions intracrâniennes et rétiniennes","contenu":"<h4>Pourquoi le nourrisson est vulnérable aux secousses</h4>\n      <ul>\n        <li><strong>Rapport poids tête / poids corps élevé</strong> (« grosse tête sur petit corps »)</li>\n        <li><span class=\"kw-clinique\">Hypotonie axiale</span> physiologique du nourrisson</li>\n        <li><strong>Cerveau immature</strong> (faible myélinisation)</li>\n        <li><strong>Larges espaces sous-arachnoïdiens</strong> (ballottement possible du cerveau)</li>\n      </ul>\n\n      <table >\n        <thead><tr><th>Cible</th><th>Mécanisme</th><th><span class=\"kw-clinique\">Lésion</span> produite</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Intracrânienne</strong></td>\n            <td><span class=\"kw-clinique\">Accélérations-décélérations brutales antéro-postérieures</span> de la tête → ballottement du cerveau dans la boîte crânienne → <strong>arrachement des veines ponts</strong> situées à la convexité</td>\n            <td><span class=\"kw-alerte\">HSD</span> de la convexité (manifestation <span class=\"kw-etio\">hémorragique</span> principale)</td>\n          </tr>\n          <tr>\n            <td><strong>Rétinienne</strong></td>\n            <td>\n              <ul>\n                <li><strong>Traction du vitré sur la rétine</strong> par <span class=\"kw-clinique\">les</span> accélérations-décélérations → arrachement des capillaires rétiniens</li>\n                <li>Mécanismes associés discutés : impact orbitaire direct (lésions palpébrales), <strong>hyperpression veineuse oculaire</strong> par ↑ pression intrathoracique (doigts de l’auteur) et ↑ pression intracrânienne (HSD, <span class=\"kw-clinique\">œdème</span>)</li>\n              </ul>\n            </td>\n            <td><span class=\"kw-alerte\">Hémorragies rétiniennes</span> ± hémorragie du vitré</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Triade pathognomonique « presque ».</strong> HSD de la convexité + hémorragies rétiniennes multiples profuses + lésions cérébrales hypoxo-anoxiques = tableau évocateur de SBS. <em>Quasi-pathognomonique</em> mais non absolu (DD : DGCDH, Menkes, complication d’accouchement).\n      </div>","frequence":0},{"id":"57-4","rang":"A","rubrique":"Diagnostic positif","titre":"Nourrisson : savoir évoquer un syndrome du bébé secoué et connaître la conduite diagnostique","contenu":"<div class=\"callout callout-warn\">\n        <strong><span class=\"kw-alerte\">Hospitalisation</span> en <span class=\"kw-alerte\">urgence</span>.</strong> Toute suspicion de SBS = <span class=\"kw-alerte\">hospitalisation en urgence</span> 🏥 pour bilan paraclinique exhaustif et mise à l’abri.\n      </div>\n\n      <h4>Signes cliniques évocateurs</h4>\n\n      <table >\n        <thead><tr><th>Axe</th><th>Signes</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Généraux</strong></td>\n            <td><span class=\"kw-clinique\">Pâleur</span>, <span class=\"kw-alerte\">malaise grave</span>, pauses respiratoires, irritabilité</td>\n          </tr>\n          <tr>\n            <td><strong>Digestifs</strong></td>\n            <td><span class=\"kw-clinique\">Vomissements</span>, <strong>sans <span class=\"kw-clinique\">diarrhée</span></strong> ⚠️ (distingue de la GEA)</td>\n          </tr>\n          <tr>\n            <td><strong>Neurologiques</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-alerte\">Bombement de la fontanelle antérieure</span></li>\n                <li><span class=\"kw-clinique\">Convulsions</span>, hypotonie axiale, troubles de vigilance</li>\n                <li><strong>Arrêt des acquisitions ou régression psychomotrice</strong></li>\n                <li>Changement de couloir de la courbe du <strong>périmètre crânien</strong></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Bilan paraclinique systématique (enfant &lt;<span class=\"kw-chiffre\"> 2 ans</span>)</h4>\n\n      <table >\n        <thead><tr><th>Examen</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Imagerie cérébrale</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-imagerie\">TDM cérébrale</span> avec reconstruction 3D, <strong>descendant jusqu’en C6</strong></li>\n                <li><span class=\"kw-imagerie\">IRM cérébrale et médullaire</span> en <span class=\"kw-bio\">complément</span> (ou en 1ʳᵉ intention si absence de symptôme neuro)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>RX squelette complet</strong></td>\n            <td>Protocole d’analyse <strong>segment par segment</strong>, <span class=\"kw-clinique\">relu par 2 radiologues spécialisés en pédiatrie</span>. Si bilan douteux ou suspicion forte : <span class=\"kw-imagerie\">scintigraphie</span> osseuse ou <strong>RX de contrôle à<span class=\"kw-chiffre\"> 10 jours</span></strong></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">Échographie</span> abdo</strong></td>\n            <td>Recherche <span class=\"kw-clinique\">lésion</span> profonde ; <span class=\"kw-imagerie\">TDM-AP</span> si anormale ou discordance clinique</td>\n          </tr>\n          <tr>\n            <td><strong>Examen ophtalmo</strong></td>\n            <td><span class=\"kw-clinique\">Fond d’œil</span> au minimum, dans <span class=\"kw-clinique\">les</span> <strong>&lt;<span class=\"kw-chiffre\"> 48 h</span></strong> suivant le traumatisme ; photos du <span class=\"kw-imagerie\">FO</span> si anomalie</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">EEG</span></strong></td>\n            <td>Recherche de crises infracliniques</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Bilan <span class=\"kw-ttt\">biologique</span> devant HSD ou suspicion SBS</h4>\n      <ul>\n        <li><strong><span class=\"kw-bio\">NFS</span>, bilan d’hémostase complet, <span class=\"kw-bio\">ionogramme sanguin</span></strong></li>\n        <li><strong>Bilan du cuivre</strong> (cuprémie, cuprurie, céruléoplasmine) : recherche d’une <span class=\"kw-etio\">maladie de Menkes</span></li>\n        <li><span class=\"kw-bio\">Chromatographie des acides organiques urinaires</span> : recherche d’une <strong>acidurie glutarique de type 1</strong> (DGCDH)</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 11 — Vilolence et santé · 47 — <span class=\"kw-def\">Suivi</span> d'un nourrisson, d'un enfant, d'un adolescent</em></p>","frequence":2,"liens":[{"href":"https://radiopaedia.org/articles/abusive-head-trauma","label":"Radiopaedia : Abusive head trauma (SBS)"}]},{"id":"57-5","rang":"A","rubrique":"Diagnostic positif","titre":"Nourrisson : connaître les lésions associées au syndrome du bébé secoué","contenu":"<table >\n        <thead><tr><th>Topographie</th><th>Lésions</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Intracrâniennes</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-alerte\">HSD</span> (<span class=\"kw-clinique\">lésion</span>-clé du SBS, hyperdensité en croissant à la convexité)</li>\n                <li><span class=\"kw-alerte\">HSA</span> ± associée</li>\n                <li><strong><span class=\"kw-clinique\">Œdème</span> cérébral</strong></li>\n                <li><strong>Fractures cranio-faciales</strong></li>\n                <li>Lésions <span class=\"kw-alerte\">hypoxo-anoxiques</span> (hypodensité substance blanche / cortex / noyaux gris)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Médullaires</strong></td>\n            <td>Lésions du rachis cervical (d’où l’imagerie descendant jusqu’en <strong>C6</strong>)</td>\n          </tr>\n          <tr>\n            <td><strong>Ophtalmologiques</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-alerte\">Hémorragies rétiniennes</span> dans <strong><span class=\"kw-chiffre\">80 %</span> des cas</strong></li>\n                <li><strong>Quasi-pathognomoniques si multiples</strong>, profuses ou éclaboussant la rétine jusqu’à sa périphérie</li>\n                <li><span class=\"kw-clinique\">Œdème</span> papillaire si <span class=\"kw-alerte\">HTIC</span> associée</li>\n                <li>Hémorragie du vitré possible</li>\n                <li>⚠️ Non pathognomoniques car aussi décrites après AVP et après accouchement chez le nouveau-né</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Lésions associées</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Lésions tégumentaires sentinelles</span> (<span class=\"kw-clinique\">ecchymoses</span>, hématomes)</li>\n                <li>Lésions ORL intrabuccales</li>\n                <li><span class=\"kw-clinique\">Fractures</span> (côtes — arcs postérieurs/moyens — métaphysaires, crâne)</li>\n                <li>Lésions viscérales abdominales</li>\n                <li>Intoxications, signes de violences sexuelles associées</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Triade-clé.</strong> <em>HSD de la convexité + hémorragies rétiniennes multiples + lésions hypoxo-anoxiques</em> = signature radio-clinique du SBS. À compléter systématiquement par la <strong>recherche de lésions sentinelles</strong> (téguments, fractures, sphère ORL).\n      </div>","frequence":2},{"id":"57-6","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître l’indication de l’imagerie devant une suspicion de maltraitance d’enfant","contenu":"<p>L’imagerie systématique d’un enfant suspect de maltraitance dépend de son <strong>âge</strong> : exhaustivité chez le &lt;<span class=\"kw-chiffre\"> 2 ans</span> (asymptomatique compris), à la carte chez le &gt;<span class=\"kw-chiffre\"> 2 ans</span>.</p>\n\n      <table >\n        <thead><tr><th>Âge</th><th>Examens systématiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Enfant &lt;<span class=\"kw-chiffre\"> 2 ans</span></strong><br><em>(même asymptomatique)</em></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-imagerie\">RX squelette complet</span> avec protocole segment par segment ; <strong>relu par 2 radiologues pédiatres</strong></li>\n                <li>Si douteux ou suspicion forte : <span class=\"kw-imagerie\">scintigraphie osseuse</span> OU <strong>contrôle RX à<span class=\"kw-chiffre\"> 10 jours</span></strong> (lésions passées inaperçues)</li>\n                <li><span class=\"kw-imagerie\">TDM cérébrale</span> (3D, jusqu’en C6)</li>\n                <li><span class=\"kw-imagerie\">IRM cérébrale et médullaire</span> (<span class=\"kw-bio\">complément</span> ou 1ʳᵉ intention si pas de signe neuro)</li>\n                <li><span class=\"kw-imagerie\">Échographie abdominale</span> ; <strong><span class=\"kw-imagerie\">TDM</span>-AP</strong> si anormale ou discordance clinique</li>\n                <li><strong><span class=\"kw-imagerie\">FO</span></strong> dans <span class=\"kw-clinique\">les</span> &lt;<span class=\"kw-chiffre\"> 48 h</span> post-trauma</li>\n                <li><strong><span class=\"kw-imagerie\">EEG</span></strong> à la recherche de crises infracliniques</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Enfant &gt;<span class=\"kw-chiffre\"> 2 ans</span></strong></td>\n            <td>Imageries <strong>au cas par cas</strong>, en fonction de la clinique</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Pourquoi le &lt;<span class=\"kw-chiffre\"> 2 ans</span> est traité comme un cas grave d’emblée.</strong> Un nourrisson <em>ne raconte pas</em> son traumatisme, ses lésions peuvent rester silencieuses, et la fenêtre médico-légale (datation des lésions) impose un bilan exhaustif tant que la maltraitance n’est pas écartée.\n      </div>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/suspected-physical-abuse-1","label":"Radiopaedia : Suspected physical abuse"}]},{"id":"57-7","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître la sémiologie tomodensitométrique (TDM) du « syndrome du bébé secoué » (HSD, HED)","contenu":"<table >\n        <thead><tr><th><span class=\"kw-clinique\">Lésion</span></th><th>Sémiologie <span class=\"kw-imagerie\">TDM</span></th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-alerte\">HSD</span></strong><br><em>(<span class=\"kw-clinique\">lésion</span> typique du SBS)</em></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-imagerie\">Hyperdensité en croissant</span> à la convexité, <strong>extraparenchymateuse</strong></li>\n                <li>Habituellement <strong>plurifocaux</strong>, uni- ou bilatéraux</li>\n                <li>Topographies évocatrices : <strong>faux du cerveau</strong>, <strong>tente du cervelet</strong> (fosse postérieure)</li>\n                <li>Prédominance des hyperdensités au <strong>vertex</strong> = signe la <em><span class=\"kw-alerte\">rupture</span>-arrachement des veines ponts</em></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>HSA associée</strong></td>\n            <td>Peut accompagner l’HSD, dans <span class=\"kw-clinique\">les</span> sillons corticaux et les citernes</td>\n          </tr>\n          <tr>\n            <td><strong>Lésions cérébrales</strong></td>\n            <td>\n              <ul>\n                <li><strong>Anoxiques :</strong> hypodensité de la substance blanche, du cortex ou des noyaux gris</li>\n                <li><strong>Œdémateuses</strong></li>\n                <li><strong>Contusions</strong></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Fractures</strong></td>\n            <td>Fractures crânio-faciales en fenêtre osseuse</td>\n          </tr>\n          <tr>\n            <td><strong>HED</strong> <em>(à distinguer)</em></td>\n            <td><span class=\"kw-imagerie\">Hyperdensité biconvexe (lentille)</span> entre os et dure-mère, <strong>ne franchit pas <span class=\"kw-clinique\">les</span> sutures</strong> — typiquement post-traumatisme à impact (chute, AVP), <em>moins évocateur</em> de SBS isolé</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>HSD <span class=\"kw-bio\">vs</span> HED — distinction sémiologique.</strong> HSD = <em>croissant qui suit la convexité et franchit <span class=\"kw-clinique\">les</span> sutures</em> (mécanisme veineux, secouement). HED = <em>biconvexe, limité par les sutures</em> (mécanisme artériel, impact direct).\n      </div>","frequence":0},{"id":"57-8","rang":"B","rubrique":"Contenu multimédia","titre":"Exemple de TDM dans un « syndrome du bébé secoué » chez un nourrisson","contenu":"<p>Image-type attendue : <span class=\"kw-imagerie\">TDM cérébrale sans injection</span> en coupe axiale, montrant une <strong>hyperdensité spontanée en croissant</strong> à la convexité (HSD), souvent <em>bilatérale et plurifocale</em>, associée à un <strong><span class=\"kw-clinique\">œdème</span> cérébral diffus</strong> (effacement des sillons, dédifférenciation substance blanche / substance grise).</p>\n\n      <h4>Sémiologie attendue sur l’image-type</h4>\n      <ul>\n        <li><span class=\"kw-imagerie\">HSD en croissant</span> à la convexité (hyperdensité spontanée extraparenchymateuse)</li>\n        <li>Atteinte <strong>plurifocale</strong>, prédominance au <strong>vertex</strong> ± faux du cerveau ± tente du cervelet</li>\n        <li>± <strong>HSA</strong> dans <span class=\"kw-clinique\">les</span> sillons</li>\n        <li><span class=\"kw-clinique\">Œdème</span> cérébral / lésions hypoxo-anoxiques : <strong>hypodensité diffuse</strong> de la substance blanche</li>\n        <li>Rechercher fractures crâniennes en fenêtre osseuse</li>\n      </ul>\n\n      <figure>\n        <img src=\"../assets/images/57/tdm-sbs-hsd-hed.png\" alt=\"TDM cérébrale sans injection chez un nourrisson de 6 mois : hématomes sous-duraux hyperdenses multifocaux à la convexité et au vertex, en faveur d'un syndrome du bébé secoué\">\n        <figcaption><strong><span class=\"kw-imagerie\">TDM</span> cérébrale sans injection (nourrisson <span class=\"kw-chiffre\">6 mois</span>)</strong> : <span class=\"kw-radio\">hématomes sous-duraux hyperdenses</span> à la convexité, <strong>multifocaux</strong> (faux du cerveau, vertex). La <strong>densité variable</strong> des hématomes (hyper/iso/hypodense) est sans rapport avec l'ancienneté du saignement. <span class=\"kw-alerte\">HSD multifocaux avant 1 an</span> → suspecter un traumatisme non accidentel. <em>Source : banque imagerie « Imagerie à connaître » (item 57).</em></figcaption>\n      </figure>","frequence":0},{"id":"57-9","rang":"A","rubrique":"Étiologie","titre":"Nourrisson : connaître les diagnostics différentiels et mécanismes lésionnels à éliminer (SBS)","contenu":"<p>Avant de retenir un SBS, éliminer formellement <span class=\"kw-clinique\">les</span> <strong>diagnostics différentiels</strong> qui peuvent mimer une triade évocatrice (HSD + hémorragies rétiniennes + atteinte neuro).</p>\n\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Diagnostic différentiel</span></th><th>Caractéristiques discriminantes</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Traumatisme crânien accidentel</strong></td>\n            <td>\n              <ul>\n                <li><strong>Chute de &lt; 1,5 mètre</strong> ⭐ : <span class=\"kw-alerte\">ne peut pas</span> causer d’HSD ni d’hémorragies rétiniennes ❌</li>\n                <li>Diagnostic retenu si : circonstances connues, non changeantes, décrites similairement par <span class=\"kw-clinique\">les</span> témoins, cinétique <strong>&gt; 1,5 m</strong></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Malformations vasculaires cérébrales / anévrysmes</strong></td>\n            <td><span class=\"kw-imagerie\">IRM + angio-IRM</span> font le diagnostic. <strong>Exceptionnelles avant l’âge de <span class=\"kw-chiffre\">1 an</span></strong></td>\n          </tr>\n          <tr>\n            <td><strong>Complications de l’accouchement</strong></td>\n            <td>Accouchement par voie basse peut entraîner des <strong>hémorragies rétiniennes</strong> chez le nouveau-né (DD à connaître pour <span class=\"kw-clinique\">les</span> <span class=\"kw-imagerie\">FO</span> précoces)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Acidurie glutarique de type 1</span></strong><br><em>(déficit en glutaryl-CoA déshydrogénase, DGCDH)</em></td>\n            <td>\n              <ul>\n                <li>Crise encéphalopathique aiguë initiale entre <strong>3 et <span class=\"kw-chiffre\">36 mois</span></strong></li>\n                <li><span class=\"kw-clinique\">Hypotonie</span>, perte des capacités motrices, <span class=\"kw-clinique\">convulsions</span></li>\n                <li>Imagerie : <strong><span class=\"kw-clinique\">lésion</span> striatale bilatérale</strong>, parfois hémorragie rétinienne et sous-durale</li>\n                <li>Diagnostic : <span class=\"kw-bio\">chromatographie des acides organiques urinaires</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Maladie de Menkes</span></strong></td>\n            <td>\n              <ul>\n                <li>Maladie <span class=\"kw-etio\">congénitale</span> rare du <strong>métabolisme du cuivre</strong></li>\n                <li>À la naissance : <strong>fractures spontanées</strong>, céphalohématomes</li>\n                <li><span class=\"kw-clinique\">Évolution</span> : retard de croissance, difficultés d’alimentation, détérioration motrice (hypotonie puis spasticité)</li>\n                <li>Diagnostic : <span class=\"kw-bio\">cuprémie / cuprurie / céruléoplasmine</span></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Règle d’or pédiatrique.</strong> <em>HSD ou hémorragies rétiniennes</em> chez un nourrisson sans cinétique élevée connue = <span class=\"kw-alerte\">SBS jusqu’à preuve du contraire</span>. <span class=\"kw-clinique\">Les</span> DD doivent être éliminés par le bilan, jamais présumés.\n      </div>","frequence":0},{"id":"57-10","rang":"A","rubrique":"Diagnostic positif","titre":"Nourrisson, enfant : savoir évoquer un syndrome de Silverman","contenu":"<p>Le <span class=\"kw-clinique\">syndrome de Silverman</span> se définit par la <span class=\"kw-def\">découverte radiologique chez un nourrisson de lésions osseuses d’âges différents</span>, en lien avec des traumatismes infligés et <strong>sans expression clinique repérée</strong>.</p>\n\n      <div class=\"callout callout-warn\">\n        <strong>Règle d’or.</strong> Plus la découverte de <span class=\"kw-clinique\">lésion</span> osseuse est <em>fortuite</em> (RX faite pour une autre raison, sans contexte traumatique rapporté), <strong>plus le risque de traumatisme infligé est élevé</strong> ⚠️.\n      </div>\n\n      <h4>Lésions osseuses évocatrices à savoir reconnaître</h4>\n      <ul>\n        <li><span class=\"kw-imagerie\">Fractures diaphysaires</span> récentes ou anciennes (cals osseux)</li>\n        <li><span class=\"kw-imagerie\">Lésions métaphysaires</span> avec <strong>arrachements en coin</strong> ou en <strong>« anse de seau »</strong> — mécanismes de traction ± torsion</li>\n        <li><span class=\"kw-imagerie\">Lésions périostées</span> : décollements du périoste par mécanismes de torsion</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Quand évoquer le diagnostic au lit du malade.</strong> Toute <em>fracture chez un nourrisson qui ne se déplace pas</em> ou sans traumatisme particulier rapporté doit conduire à une <span class=\"kw-alerte\">hospitalisation</span> 🏥 pour bilan exhaustif (cf. <span class=\"kw-clinique\">lésion</span> sentinelle avant l’âge de la marche).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 47 — <span class=\"kw-def\">Suivi</span> d'un nourrisson, d'un enfant, d'un adolescent</em></p>","frequence":2},{"id":"57-11","rang":"A","rubrique":"Définition","titre":"Nourrisson, enfant : connaître la définition du syndrome de Silverman","contenu":"<table >\n        <tbody>\n          <tr>\n            <td><strong>Définition</strong></td>\n            <td><span class=\"kw-def\">Découverte radiologique</span> chez un <strong>nourrisson</strong> de <strong>lésions osseuses d’âges différents</strong>, en lien avec des traumatismes infligés et <em>sans expression clinique repérée</em></td>\n          </tr>\n          <tr>\n            <td><strong>Caractère essentiel</strong></td>\n            <td>Diagnostic <strong>radiologique</strong> (et non clinique) — <span class=\"kw-clinique\">les</span> lésions ont guéri ou évoluent sans symptôme apparent</td>\n          </tr>\n          <tr>\n            <td><strong>Spécificité de l’âge</strong></td>\n            <td>Décrit chez le <span class=\"kw-clinique\">nourrisson</span> ; <span class=\"kw-clinique\">les</span> fractures multiples d’âges différents chez l’enfant plus grand entrent dans le cadre élargi de la <em>maltraitance physique</em></td>\n          </tr>\n          <tr>\n            <td><strong>Risque</strong></td>\n            <td>Plus la découverte est <strong>fortuite</strong>, plus le risque de <span class=\"kw-alerte\">traumatisme infligé</span> est élevé ⚠️</td>\n          </tr>\n        </tbody>\n      </table>","frequence":0},{"id":"57-12","rang":"A","rubrique":"Diagnostic positif","titre":"Nourrisson, enfant : connaître la conduite diagnostique en cas de suspicion de syndrome de Silverman","contenu":"<div class=\"callout callout-warn\">\n        <strong><span class=\"kw-alerte\">Hospitalisation</span> systématique.</strong> Survenue d’une fracture chez un nourrisson non déambulant ou sans traumatisme rapporté = <span class=\"kw-alerte\">hospitalisation</span> 🏥 pour bilan exhaustif et mise à l’abri.\n      </div>\n\n      <h4>Bilan d’imagerie (enfant &lt;<span class=\"kw-chiffre\"> 2 ans</span> systématique)</h4>\n      <ul>\n        <li><span class=\"kw-imagerie\">RX squelette complet</span>, protocole d’analyse <strong>segment par segment</strong>, <strong>relu par 2 radiologues pédiatres</strong></li>\n        <li>Si bilan douteux ou suspicion forte : <span class=\"kw-imagerie\">scintigraphie osseuse</span> ou <strong>RX de contrôle à<span class=\"kw-chiffre\"> 10 jours</span></strong> (objective des lésions passées inaperçues)</li>\n        <li><span class=\"kw-imagerie\">TDM cérébrale</span> + <span class=\"kw-imagerie\">IRM cérébrale et médullaire</span> (recherche lésions associées SBS)</li>\n        <li><span class=\"kw-imagerie\">Échographie abdo</span> (<span class=\"kw-clinique\">lésion</span> profonde)</li>\n        <li><strong><span class=\"kw-imagerie\">FO</span></strong> (hémorragies rétiniennes)</li>\n      </ul>\n\n      <h4>Bilan <span class=\"kw-ttt\">biologique</span> devant lésions osseuses</h4>\n      <ul>\n        <li><strong>Biologie sanguine :</strong> <span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">VS</span>, <span class=\"kw-bio\">CRP</span>, <span class=\"kw-bio\">bilan hépatique</span> (<span class=\"kw-bio\">PAL</span>), <span class=\"kw-bio\">bilan rénal</span> (<span class=\"kw-bio\">créatinine</span>), iono sanguin</li>\n        <li><span class=\"kw-bio\">Calcémie, phosphorémie, PTH, vitamine D</span> (élimine rachitisme)</li>\n        <li><strong>Biologie urinaire :</strong> iono urinaire, créat urinaire, <span class=\"kw-bio\">protéinurie</span><span class=\"kw-chiffre\"> 24 h</span>, <strong>calciurie <span class=\"kw-chiffre\">24 h</span></strong>, phosphaturie <span class=\"kw-chiffre\">24 h</span>, taux de réabsorption tubulaire du phosphore</li>\n      </ul>\n\n      <h4>Démarche médico-légale conjointe</h4>\n      <ul>\n        <li><strong><span class=\"kw-bio\">CMI</span></strong> systématique (description des lésions sans interprétation)</li>\n        <li><span class=\"kw-alerte\">Hospitalisation</span> en <span class=\"kw-clinique\">UAPED</span> si disponible</li>\n        <li><strong>Information préoccupante (CRIP)</strong> ou <strong><span class=\"kw-def\">signalement</span> judiciaire</strong> selon <span class=\"kw-alerte\">urgence</span> et danger</li>\n        <li><strong>Examen de la fratrie</strong> systématique en cas de suspicion de maltraitance</li>\n      </ul>","frequence":0},{"id":"57-13","rang":"A","rubrique":"Diagnostic positif","titre":"Nourrisson, enfant : connaître les lésions associées au syndrome de Silverman","contenu":"<table >\n        <thead><tr><th>Type de <span class=\"kw-clinique\">lésion</span></th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Fractures des côtes</strong></td>\n            <td><span class=\"kw-imagerie\">Arcs moyens ou postérieurs</span> ⭐ (mécanisme : bébé serré fortement ou secoué)</td>\n          </tr>\n          <tr>\n            <td><strong>Fractures métaphysaires</strong></td>\n            <td>Petits <strong>arrachements osseux</strong> par gestes de <em>traction et torsion</em> — coin ou « anse de seau »</td>\n          </tr>\n          <tr>\n            <td><strong>Fractures du crâne</strong></td>\n            <td>± associées au SBS</td>\n          </tr>\n          <tr>\n            <td><strong>Décollements épiphysaires</strong></td>\n            <td><strong>Humérus distal et proximal, fémur</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Réactions périostées</strong></td>\n            <td>Décollements du périoste par <em>torsion</em></td>\n          </tr>\n          <tr>\n            <td><strong>Fractures diaphysaires</strong></td>\n            <td>\n              <ul>\n                <li><strong>Coup direct :</strong> trait <em>transverse</em></li>\n                <li><strong>Torsion :</strong> trait <em>oblique ou spiroïde</em></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Cals osseux</strong></td>\n            <td>Marqueurs de <span class=\"kw-alerte\">fractures anciennes</span> non rapportées par <span class=\"kw-clinique\">les</span> parents</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Lésions « plurifocales et d’âges différents ».</strong> La signature radiologique du Silverman est la <em>coexistence</em> de lésions récentes (trait fin) et anciennes (cals), incompatibles avec un événement traumatique unique rapporté par <span class=\"kw-clinique\">les</span> parents.\n      </div>","frequence":0},{"id":"57-14","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître la sémiologie en radiographie d’un traumatisme non accidentel","contenu":"<p>La sémiologie RX d’un traumatisme infligé repose sur <strong>localisations, traits de fracture et coexistence de lésions d’âges différents</strong>.</p>\n\n      <table >\n        <thead><tr><th>Critère</th><th>Sémiologie évocatrice</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Topographie évocatrice</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-imagerie\">Côtes (arcs postérieurs/moyens)</span> ⭐ — bébé serré ou secoué</li>\n                <li><span class=\"kw-imagerie\">Métaphyses</span> — humérus, fémur, tibia (traction / torsion)</li>\n                <li><span class=\"kw-imagerie\">Crâne</span></li>\n                <li>Décollements épiphysaires (humérus distal/proximal, fémur)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Type de trait diaphysaire</strong></td>\n            <td>\n              <ul>\n                <li><strong>Transverse :</strong> coup direct</li>\n                <li><strong>Oblique ou spiroïde :</strong> torsion</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Coexistence d’âges</strong></td>\n            <td>Présence de <span class=\"kw-alerte\">cals osseux</span> (fracture ancienne) + trait récent = signature forte</td>\n          </tr>\n          <tr>\n            <td><strong>Réactions périostées</strong></td>\n            <td>Décollements périostés par torsion</td>\n          </tr>\n          <tr>\n            <td><strong>Protocole de lecture</strong></td>\n            <td>RX squelette complet, <strong>segment par segment</strong>, <strong>relu par 2 radiologues pédiatres</strong></td>\n          </tr>\n          <tr>\n            <td><strong>2ᵉ regard à 10 j</strong></td>\n            <td>RX de contrôle à <strong><span class=\"kw-chiffre\">10 jours</span></strong> ou <span class=\"kw-imagerie\">scintigraphie osseuse</span> si suspicion forte avec 1ᵉ⁻ bilan douteux</td>\n          </tr>\n        </tbody>\n      </table>","frequence":0},{"id":"57-15","rang":"B","rubrique":"Contenu multimédia","titre":"Radiographie d’un traumatisme non accidentel (syndrome de Silverman)","contenu":"<p>Image-type attendue : <span class=\"kw-imagerie\">RX squelette d’un nourrisson</span> montrant des <strong>fractures multiples d’âges différents</strong>, avec lésions évocatrices :</p>\n\n      <h4>Sémiologie attendue sur l’image-type</h4>\n      <ul>\n        <li><span class=\"kw-imagerie\">Fractures des arcs postérieurs / moyens des côtes</span> (cals visibles)</li>\n        <li><span class=\"kw-imagerie\">Arrachements métaphysaires</span> en coin ou en « anse de seau » (humérus, fémur, tibia)</li>\n        <li><span class=\"kw-imagerie\">Décollement périosté</span> diaphysaire (apposition périostée linéaire fine, parallèle à la corticale)</li>\n        <li><strong>Cals osseux</strong> de fractures plus anciennes, coexistant avec des fractures récentes</li>\n        <li>± Fracture du crâne (linéaire ou complexe)</li>\n      </ul>\n\n      <figure>\n        <img src=\"../assets/images/57/rx-silverman-appositions-periostees.png\" alt=\"Radiographies des membres d'un nourrisson de 4 mois : appositions périostées ulnaires et humérales, fracture métaphyso-diaphysaire en cours de consolidation, décollements métaphysaires du tibia et de la fibula — fractures d'âges différents évoquant un syndrome de Silverman\">\n        <figcaption><strong><span class=\"kw-imagerie\">Radiographies</span> des membres (nourrisson <span class=\"kw-chiffre\">4 mois</span>)</strong> : <span class=\"kw-radio\">appositions périostées</span> ulnaires et humérales, <span class=\"kw-radio\">fracture métaphyso-diaphysaire</span> de l'ulna en cours de consolidation, <span class=\"kw-radio\">décollements métaphysaires</span> du tibia et de la fibula. <span class=\"kw-alerte\">Fractures multiples d'âges différents</span> → suspecter un traumatisme non accidentel (<span class=\"kw-clinique\">syndrome de Silverman</span>). <em>Source : banque imagerie « Imagerie à connaître » (item 57).</em></figcaption>\n      </figure>","frequence":0},{"id":"57-16","rang":"B","rubrique":"Étiologie","titre":"Nourrisson, enfant : connaître les diagnostics différentiels et mécanismes lésionnels à éliminer (Silverman)","contenu":"<table >\n        <thead><tr><th><span class=\"kw-def\">Diagnostic différentiel</span></th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Ostéogenèse imparfaite</span></strong><br><em>(« maladie des os de verre »)</em></td>\n            <td>\n              <ul>\n                <li>Maladie <span class=\"kw-etio\">génétique</span> du <strong>collagène</strong></li>\n                <li><span class=\"kw-clinique\">Déformations des os</span></li>\n                <li><span class=\"kw-imagerie\">Transparence excessive en radiographie</span></li>\n                <li>Fractures <span class=\"kw-imagerie\">diaphysaires et/ou costales</span> — <strong>pas d’arrachement métaphysaire</strong> ⚠️ (différence-clé)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Ostéomyélite</span></strong></td>\n            <td>Contexte <span class=\"kw-etio\">infectieux</span>, signes inflammatoires biologiques, atteinte focale</td>\n          </tr>\n          <tr>\n            <td><strong>Cancers / hémopathies</strong></td>\n            <td><span class=\"kw-alerte\">Leucémie aiguë lymphoblastique</span>, sarcomes osseux, métastases (neuroblastome) — bandes claires métaphysaires, atteinte multifocale</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Rachitisme</span></strong></td>\n            <td>\n              <ul>\n                <li>Carence en <strong><span class=\"kw-bio\">vitamine D</span></strong> ou maladie <span class=\"kw-etio\">génétique</span></li>\n                <li>Élargissement métaphysaire en « cupule », flou des métaphyses</li>\n                <li>Bilan : <span class=\"kw-bio\">calcémie, phosphorémie, PAL, PTH, vitamine D</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Scorbut</span></strong></td>\n            <td>Carence en <strong>vitamine C</strong> — appositions périostées par hémorragies sous-périostées</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Carences = négligences graves.</strong> <span class=\"kw-clinique\">Les</span> maladies carentielles (rachitisme, scorbut) sont des DD mais elles imposent en parallèle d’<em>éliminer une négligence grave</em>. Carence et maltraitance ne s’excluent pas.\n      </div>","frequence":0},{"id":"57-17","rang":"A","rubrique":"Définition","titre":"Enfant, adolescent : connaître la définition de la maltraitance","contenu":"<div class=\"callout callout-info\">\n        <strong>Définition OMS 🔴</strong> — <span class=\"kw-def\">Toutes les formes de mauvais traitements physiques, affectifs, sévices sexuels, négligence, exploitation commerciale ou autre, entraînant un préjudice réel ou potentiel pour la santé de l’enfant, sa survie, son développement ou sa dignité dans le contexte d’une relation de responsabilité, de confiance ou de pouvoir</span>.\n      </div>\n\n      <p>L’<strong>exposition de l’enfant au spectacle de violences entre partenaires intimes</strong> est aussi considérée comme une forme de maltraitance. <span class=\"kw-clinique\">Les</span> mineurs sont <em>rarement victimes d’un seul type de violence</em> — les autres sont toujours à rechercher.</p>\n\n      <h4>Actes par « commission »</h4>\n\n      <table >\n        <thead><tr><th>Violence</th><th>Définition / exemples</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Physiques</strong></td><td>Coups, claques, corrections...</td></tr>\n          <tr><td><strong>Sexuelles</strong></td><td>Toute participation d’un enfant à des activités sexuelles inappropriées à son âge et à son développement psychosexuel, subies sous contrainte, violence, séduction, ou transgressant <span class=\"kw-clinique\">les</span> tabous sociaux</td></tr>\n          <tr><td><strong>Psychologiques</strong></td><td><strong>Dénigrement</strong> ; <strong>humiliation</strong> ; <strong>injonction paradoxale</strong> ; <strong>rejet affectif</strong> ; punition ou exigence éducative inadaptée à l’âge ou aux possibilités de l’enfant</td></tr>\n          <tr><td><strong>Conjugales</strong></td><td>Exposition d’un enfant à des violences conjugales = situation d’une <span class=\"kw-alerte\">grande violence</span></td></tr>\n          <tr><td><strong>Cyberviolences</strong></td><td>Exposition à images violentes/pornographiques ; sexting ; happy slapping ; cyber-harcèlement</td></tr>\n          <tr><td><strong>Institutionnelles</strong></td><td>Violences subies hors famille, en milieu collectif ou cachées par <span class=\"kw-clinique\">les</span> institutions d’accueil</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Actes par « omission »</h4>\n      <ul>\n        <li><strong>Négligences :</strong> <span class=\"kw-def\">absence de réponse aux besoins fondamentaux</span> de l’enfant (sécurité, santé, scolarité, mise en collectivité...)</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Enfants en risque <span class=\"kw-bio\">vs</span> maltraités.</strong> <em>Enfants en risque</em> = pas à proprement parler maltraités, mais leurs conditions d’existence risquent de mettre en danger leurs santé, sécurité, moralité, éducation ou la qualité des réponses à leurs besoins quotidiens.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 11 — Vilolence et santé · 12 — Violences sexuelles</em></p>","frequence":0},{"id":"57-18","rang":"A","rubrique":"Identifier une urgence","titre":"Enfant, adolescent : savoir reconnaître une situation évoquant une maltraitance","contenu":"<div class=\"callout callout-warn\">\n        <strong>Examen de la fratrie obl<span class=\"kw-chiffre\">iga</span>toire.</strong> En cas de suspicion de maltraitance chez un enfant, <span class=\"kw-alerte\">l’intégralité de la fratrie doit être examinée</span>.\n      </div>\n\n      <h4>Signes d’alerte (« feux rouges » 🚩)</h4>\n\n      <table >\n        <thead><tr><th>Axe</th><th>Signes d’alerte</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Anamnèse</strong></td>\n            <td>\n              <ul>\n                <li><strong>Absence d’explication</strong> ou caractère peu plausible / incohérence par rapport aux lésions</li>\n                <li><strong>Délai</strong> entre apparition des lésions et consultation = indicateur fort de négligence</li>\n                <li><strong>Mise en cause d’un tiers</strong> (a fortiori jeune enfant ou <strong>animal domestique</strong>)</li>\n                <li>Présence de <strong>FR de maltraitance</strong></li>\n                <li>Consultations répétées pour traumatismes / accidents domestiques</li>\n                <li>Consultations répétées pour plaintes somatiques sans étiologie (douleurs abdo, <span class=\"kw-clinique\">céphalées</span>, troubles du sommeil/alimentation)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Présentation selon l’âge</strong></td>\n            <td>\n              <ul>\n                <li><strong>Nourrissons :</strong> surtout négligences et violences physiques</li>\n                <li><strong>Enfants plus grands / adolescents :</strong>\n                  <ul>\n                    <li><span class=\"kw-clinique\">TSPT</span>, trouble dépressif, trouble psychoaffectif, <strong>tentative de suicide</strong></li>\n                    <li>Auto-agressivité : scarifications, restriction alimentaire, TS</li>\n                    <li>Hétéro-agressivité : violences agies évoquant des violences subies</li>\n                    <li>Désinsertion sociale, fugues, conduites à risque, chute des résultats scolaires ou surinvestissement scolaire</li>\n                  </ul>\n                </li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Lésion</span> sentinelle</strong> ⭐</td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Lésion</span> d’allure traumatique <strong>avant l’âge de la marche</strong> = <span class=\"kw-alerte\">traumatisme infligé jusqu’à preuve du contraire</span></li>\n                <li>Lésions élémentaires <span class=\"kw-clinique\">les</span> plus fréquentes : <strong><span class=\"kw-clinique\">ecchymoses</span>, hématomes</strong></li>\n                <li>Localisations <span class=\"kw-clinique\">les</span> plus fréquentes : <strong>visage (<span class=\"kw-chiffre\">75 %</span>) &gt; tronc (<span class=\"kw-chiffre\">30 %</span>) &gt; extrémités (<span class=\"kw-chiffre\">25 %</span>)</strong></li>\n                <li>Lésions <strong>profondes associées dans &gt;<span class=\"kw-chiffre\"> 50 %</span> des cas</strong> (osseuses, abdominales, neurologiques)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Suspicion de violences sexuelles</strong></td>\n            <td>\n              <ul>\n                <li>Impose un <span class=\"kw-alerte\">signalement</span>, d’autant plus rapide si <span class=\"kw-clinique\">les</span> faits sont récents</li>\n                <li>Si faits &lt; <strong><span class=\"kw-chiffre\">5 jours</span></strong> : examen sur <strong>réquisition judiciaire</strong> par un <span class=\"kw-clinique\">médecin légiste</span> (prélèvements génétiques)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 12 — Violences sexuelles · 71 — Troubles conduite alimentaire</em></p>","frequence":1},{"id":"57-19","rang":"A","rubrique":"Diagnostic positif","titre":"Enfant, adolescent : identifier les lésions traumatiques élémentaires dans la maltraitance","contenu":"<h4><span class=\"kw-clinique\">Ecchymoses</span> suspectes</h4>\n\n      <table >\n        <thead><tr><th>Critère</th><th>Caractéristiques évocatrices</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Forme</strong></td>\n            <td><span class=\"kw-alerte\">Lésions « en forme »</span> ⚠️ (doigts, mains, ceinture, bâton, câble électrique) — évoque la <strong>mécanique traumatique et l’agent vulnérant</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Nombre</strong></td>\n            <td><strong>≥ <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>15</span> l</span>ésions cutanées</strong> chez un enfant déambulant <em>sans traumatisme ni pathologie de l’hémostase</em></td>\n          </tr>\n          <tr>\n            <td><strong>Âges différents</strong></td>\n            <td><span class=\"kw-clinique\">Ecchymoses</span> multiples de <span class=\"kw-clinique\">colorations différentes</span> (jaune / vert / violet / rouge)</td>\n          </tr>\n          <tr>\n            <td><strong>Taille</strong></td>\n            <td><span class=\"kw-clinique\">Ecchymoses</span> de <strong>grande taille</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Localisations suspectes</strong></td>\n            <td>\n              <ul>\n                <li><strong>Parties concaves :</strong> <span class=\"kw-clinique\">oreilles, joues, cou</span></li>\n                <li><strong>Zones cutanées non habituellement exposées :</strong> tronc, faces internes des bras, faces internes et postérieures des cuisses, fesses</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Autres lésions suspectes</h4>\n\n      <table >\n        <thead><tr><th><span class=\"kw-clinique\">Lésion</span></th><th>Caractéristiques évocatrices</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Brûlures</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-alerte\">Bords nets</span> évoquant immersion (« en chaussettes », « en gants ») ou « en forme » (c<span class=\"kw-chiffre\">iga</span>rettes)</li>\n                <li>Localisations : <strong>zones normalement protégées par <span class=\"kw-clinique\">les</span> vêtements</strong> (fesses, périnée)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Morsures</strong></td>\n            <td>Marques circulaires ou ovales de <strong><span class=\"kw-chiffre\">2 à 5 cm</span></strong>, formées de 2 arcs concaves opposés ± <span class=\"kw-clinique\">ecchymose</span> centrale</td>\n          </tr>\n          <tr>\n            <td><strong>Abrasions</strong></td>\n            <td>Notamment des <span class=\"kw-clinique\">poignets et chevilles</span> = contention par des liens</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Examen tégumentaire — règles pratiques</h4>\n      <ul>\n        <li>Lésions <strong>photographiées avec repère métrique et identité de l’enfant</strong>, consignées dans le dossier médical</li>\n        <li>Examen exhaustif : <strong>face postérieure des oreilles, fesses, périnée</strong> ne pas oublier</li>\n        <li>Schémas dans le dossier (taille, forme, couleur, localisation)</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 13 — Certificats médicaux · 11 — Vilolence et santé</em></p>","frequence":3},{"id":"57-20","rang":"B","rubrique":"Diagnostic positif","titre":"Enfant, adolescent : identifier le retentissement psychologique des violences","contenu":"<h4>Tableaux psychiatriques chez l’enfant et l’adolescent maltraités</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Trouble de stress post-traumatique (TSPT)</span></li>\n        <li>Trouble dépressif, trouble psychoaffectif, anxiété</li>\n        <li><span class=\"kw-alerte\">Tentatives de suicide</span> et idées suicidaires</li>\n      </ul>\n\n      <h4>Troubles du comportement</h4>\n\n      <table >\n        <thead><tr><th>Versant</th><th>Manifestations</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Auto-agressivité</strong></td>\n            <td>\n              <ul>\n                <li>Scarifications</li>\n                <li>Restriction alimentaire / <span class=\"kw-clinique\">TCA</span></li>\n                <li>Dévalorisation, repli</li>\n                <li><span class=\"kw-alerte\">Suicides et tentatives de suicide</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Hétéro-agressivité</strong></td>\n            <td>Violences agies en particulier — <em>peuvent évoquer des violences subies</em></td>\n          </tr>\n          <tr>\n            <td><strong>Autres</strong></td>\n            <td>Désinsertion sociale, fugues, conduites à risque, chute brutale des résultats scolaires <em>ou</em> surinvestissement scolaire</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Signes de psychotraumatisme complexe</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">État dissociatif</span> ⚠️ : enfant pouvant sembler indifférent aux événements (peut décrédibiliser la parole à tort)</li>\n      </ul>\n\n      <h4>Conséquences à l’âge adulte (<span class=\"kw-bio\">ACE</span> — Adverse Childhood Events)</h4>\n      <ul>\n        <li><strong>Désordres psychiques :</strong> addictions, maladies psychiatriques, dépressions, anxiété</li>\n        <li><strong>Génésiques :</strong> <span class=\"kw-clinique\">IST</span> (comportements à risque), grossesses précoces, prématurité</li>\n        <li><strong>Somatiques :</strong> pathologies traumatologiques, maladies chroniques <span class=\"kw-bio\">CV</span>, <span class=\"kw-etio\">obésité</span>, cancers</li>\n        <li>Plus enclins à <span class=\"kw-alerte\">devenir violent</span> ou à <strong>subir des violences</strong></li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 71 — Troubles conduite alimentaire</em></p>","frequence":0},{"id":"57-21","rang":"A","rubrique":"Définition","titre":"Nourrisson, enfant, adolescent : connaître la définition du signalement judiciaire, administratif et de la CRIP","contenu":"<table >\n        <thead><tr><th>Outil</th><th>Définition / cadre</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Information préoccupante (IP)</span></strong></td>\n            <td>\n              <ul>\n                <li>Tout élément d’information, y compris <strong>médical</strong>, susceptible de laisser craindre qu’un enfant se trouve en <strong>situation de danger ou de risque de danger</strong>, et puisse avoir besoin d’une aide</li>\n                <li>Transmise à la <strong>CRIP</strong> pour évaluation et suite à donner</li>\n                <li><strong>Écrit formalisé</strong> (modèles disponibles en ligne)</li>\n                <li>Parents informés <strong>sauf intérêt contraire de l’enfant</strong></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Signalement judiciaire</span></strong></td>\n            <td>\n              <ul>\n                <li>Écrit objectif portant à la connaissance du <span class=\"kw-alerte\">Procureur de la République</span> la situation d’un mineur présumé en danger (dérogation au secret professionnel)</li>\n                <li>Indications :\n                  <ul>\n                    <li><span class=\"kw-alerte\">Maltraitance grave</span></li>\n                    <li><span class=\"kw-alerte\">Protection immédiate</span> de l’enfant nécessaire</li>\n                    <li><span class=\"kw-alerte\">Enquête pénale</span> nécessaire (contexte délictuel ou criminel)</li>\n                  </ul>\n                </li>\n                <li>Modèle type téléchargeable sur le site de l’Ordre national des médecins</li>\n                <li>Mêmes règles de rédaction que l’IP</li>\n                <li><strong>Double</strong> transmissible à la CRIP (qui est toujours informée par le Procureur)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">CRIP</span></strong><br><em>(Cellule départementale de Recueil des Informations Préoccupantes)</em></td>\n            <td>\n              <ul>\n                <li>Dépend du <strong>Conseil départemental</strong></li>\n                <li>Centralise toutes <span class=\"kw-clinique\">les</span> IP ; renvoie aux centres d’action sociale dont dépend la <strong>PMI</strong></li>\n                <li><strong>Évaluation pluridisciplinaire</strong> de la situation du mineur</li>\n                <li>Délai d’évaluation : <span class=\"kw-chiffre\">3 mois</span> ⭐</li>\n                <li>Décisions possibles :\n                  <ul>\n                    <li><strong><span class=\"kw-def\">Signalement</span> judiciaire</strong> si danger confirmé ou évaluation impossible</li>\n                    <li><strong>Classement</strong> sans suite si pas de danger</li>\n                    <li><strong>Intervention administrative</strong> (AESF, TISF, action éducative, <span class=\"kw-def\">suivi</span> PMI/SSD)</li>\n                  </ul>\n                </li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>2 systèmes de protection.</strong>\n        <ul>\n          <li><span class=\"kw-clinique\">Protection administrative</span> = <strong>Conseil départemental</strong> (chef de file) → <em>CRIP</em></li>\n          <li><span class=\"kw-clinique\">Protection judiciaire</span> = <strong>Juge des enfants</strong> + <strong>Procureur de la République</strong> (urgences, OPP)</li>\n        </ul>\n      </div>\n\n      <div class=\"callout callout-info\">\n        <strong>Procureur <span class=\"kw-bio\">vs</span> Juge pour enfants.</strong>\n        <ul>\n          <li><strong>Procureur :</strong> contacté <em>en <span class=\"kw-alerte\">urgence</span></em> (OPP par ex)</li>\n          <li><strong>Juge pour enfants :</strong> décide de la suite à donner, <span class=\"kw-alerte\">n’est PAS le contact d’urgence</span> ⚠️</li>\n        </ul>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 11 — Vilolence et santé · 12 — Violences sexuelles · 13 — Certificats médicaux</em></p>","frequence":4},{"id":"57-22","rang":"B","rubrique":"Définition","titre":"Nourrisson, enfant, adolescent : connaître la définition d’une ordonnance de placement provisoire","contenu":"<table >\n        <tbody>\n          <tr>\n            <td><strong>Définition</strong></td>\n            <td>Mesure de <span class=\"kw-def\">placement</span> ordonnée en <span class=\"kw-alerte\">urgence</span> pour confier un enfant à un tiers, à un autre membre de la famille, à un service ou à un foyer</td>\n          </tr>\n          <tr>\n            <td><strong>Qui ordonne ?</strong></td>\n            <td>\n              <ul>\n                <li><strong>Juge des enfants</strong> (cadre habituel)</li>\n                <li>En <span class=\"kw-alerte\">cas d’urgence</span>, le <strong>Parquet</strong> (Procureur) peut <em>lui-même</em> ordonner une OPP <strong>avant</strong> de saisir le juge des enfants</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Forme</strong></td>\n            <td>Décision <strong>motivée</strong> et <strong>notifiée aux titulaires de l’autorité parentale</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Recours</strong></td>\n            <td><span class=\"kw-alerte\">Aucun recours possible</span> pour <span class=\"kw-clinique\">les</span> parents ⚠️</td>\n          </tr>\n          <tr>\n            <td><strong>Durée</strong></td>\n            <td>Placement valable <span class=\"kw-chiffre\">8 jours</span> ⭐</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Quand l’OPP est-elle utilisée ?</strong> Refus d’<span class=\"kw-alerte\">hospitalisation</span> par <span class=\"kw-clinique\">les</span> parents + situation de danger immédiat → <span class=\"kw-def\">signalement</span> judiciaire au Procureur, qui peut ordonner une OPP en <span class=\"kw-alerte\">urgence</span> pour protéger l’enfant.\n      </div>","frequence":0},{"id":"57-23","rang":"B","rubrique":"Définition","titre":"Nourrisson, enfant, adolescent : connaître la définition d’une réquisition judiciaire","contenu":"<table >\n        <tbody>\n          <tr>\n            <td><strong>Définition</strong></td>\n            <td><span class=\"kw-def\">Demande adressée par l’autorité judiciaire</span> (Procureur, OPJ) à un médecin pour réaliser un acte médical (examen, prélèvement, certificat descriptif) dans le cadre d’une enquête</td>\n          </tr>\n          <tr>\n            <td><strong>Indications classiques</strong></td>\n            <td>\n              <ul>\n                <li>Violences sexuelles datant de <span class=\"kw-alerte\">&lt; 5 jours</span> ⭐ → examen par un <strong>médecin légiste</strong> (prélèvements génétiques)</li>\n                <li>Certificat descriptif avec questions spécifiques (compatibilité lésions / faits rapportés)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Règles de rédaction</strong></td>\n            <td>Mêmes règles que le <span class=\"kw-bio\">CMI</span> ; la réquisition peut <strong>poser des questions supplémentaires</strong> spécifiques</td>\n          </tr>\n          <tr>\n            <td><strong>Si compétence insuffisante</strong></td>\n            <td>Le praticien <strong>doit néanmoins répondre</strong> à l’autorité judiciaire et signaler son manque de compétence dans la réponse</td>\n          </tr>\n          <tr>\n            <td><strong>Différence avec expertise</strong></td>\n            <td>\n              <ul>\n                <li>Réquisition <strong>≠ expertise</strong> sur fond et sur forme</li>\n                <li><span class=\"kw-alerte\">Le juge n’est pas lié</span> aux conclusions de la réquisition (peut modifier la durée d’une ITT fixée, par ex.)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 13 — Certificats médicaux · 12 — Violences sexuelles</em></p>","frequence":0},{"id":"57-24","rang":"A","rubrique":"Épidémiologie","titre":"Maltraitance et enfants en danger : connaître l’épidémiologie","contenu":"<p>L’<span class=\"kw-def\">épidémiologie</span> française de la maltraitance est <em>imprécise</em>, fondée sur des évaluations anciennes : absence d’homogénéité des données statistiques. Travail en cours sous l’égide de l’<span class=\"kw-clinique\">ONPE (ex-ONED)</span> et du <span class=\"kw-clinique\">CNPE</span> (Conseil National de la Protection de l’Enfance).</p>\n\n      <table >\n        <thead><tr><th>Chiffre-clé</th><th>Valeur</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Mineurs sous protection (31/12/2020)</strong></td>\n            <td><span class=\"kw-alerte\">308 000</span> mineurs en France (hors Mayotte) bénéficiant d’au moins une prestation/mesure du dispositif de protection de l’enfance — <strong>21,4 pour 1 <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>000</span> min</span>eurs</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Décès intrafamiliaux (2020)</strong></td>\n            <td><span class=\"kw-alerte\">49 enfants</span> décédés dans le cadre intrafamilial</td>\n          </tr>\n          <tr>\n            <td><strong>Décès UNICEF</strong></td>\n            <td><span class=\"kw-alerte\">3 mineurs &lt; 15 ans</span> décèdent <strong>par semaine</strong> en France suite à des situations de maltraitance</td>\n          </tr>\n          <tr>\n            <td><strong>Mineurs en danger</strong></td>\n            <td>Fréquent en pratique pédiatrique : concerne <span class=\"kw-alerte\">&gt; 1 enfant sur 10</span></td>\n          </tr>\n          <tr>\n            <td><strong>SBS (<span class=\"kw-def\">incidence</span> France)</strong></td>\n            <td>Environ <strong>200 enfants/an</strong> victimes en France</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Repérage = enjeu de santé publique.</strong> Sous-déclaration majeure : <span class=\"kw-clinique\">les</span> chiffres officiels sous-estiment la réalité. Tout médecin de premier recours doit savoir repérer une situation à risque et activer le circuit IP / <span class=\"kw-def\">signalement</span>.\n      </div>","frequence":1},{"id":"57-25","rang":"A","rubrique":"Diagnostic positif / Examen C","titre":"Maltraitance et enfants en danger : connaître les modalités de l’enquête clinique","contenu":"<h4>3 circonstances diagnostiques (à connaître)</h4>\n      <ol>\n        <li>Enfant a <strong>révélé des violences</strong> qui sont le motif de la consultation</li>\n        <li>Enfant accompagné par un parent ou un tiers qui <strong>suspecte des violences, négligences ou danger</strong></li>\n        <li><strong>Présentation clinique</strong> du mineur (lésions cutanées/muqueuses, tableaux neuro, <span class=\"kw-alerte\">détresse</span> psychique, <span class=\"kw-clinique\">IST</span>...) faisant poser la question des violences ou négligences</li>\n      </ol>\n\n      <h4>3 axes forts de réponse</h4>\n      <ul>\n        <li>Cet enfant nécessite-t-il des <strong>soins</strong> (<span class=\"kw-ttt\">antalgique</span>, paraclinique, accompagnements) → si oui, lesquels, et avec quel <span class=\"kw-alerte\">degré d’urgence</span> ?</li>\n        <li><strong>Consigner dans le dossier</strong> ce qui a été constaté : circonstances (tiers présent, propos spontanés ou questionnés), données cliniques (forme, taille, couleur, localisation), présentation générale (douleur, hygiène, rapport à l’examinateur, développement psychoaffectif)</li>\n        <li>La <strong>protection</strong> du mineur est-elle assurée ? Sinon, <span class=\"kw-alerte\">hospitalisation</span> à envisager facilement (mise à l’abri, accueil de la parole)</li>\n      </ul>\n\n      <h4>Modalités d’examen</h4>\n\n      <table >\n        <thead><tr><th>Axe</th><th>Démarche</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Interrogatoire</strong></td>\n            <td>\n              <ul>\n                <li>Si accident domestique / traumatisme : détailler <strong>circonstances de survenue</strong> (compatibilité ? délai ?)</li>\n                <li>Rechercher <span class=\"kw-clinique\">les</span> <strong>FR de maltraitance</strong></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Carnet de santé</strong></td>\n            <td>Outil <strong>indispensable</strong> : situation périnatale, <span class=\"kw-clinique\">qualité du suivi médical</span>, développement psychoaffectif, vaccinations, courbes staturo-pondérales, handicap/maladie chronique</td>\n          </tr>\n          <tr>\n            <td><strong>Examen global</strong></td>\n            <td>\n              <ul>\n                <li>Poids, taille, <strong>périmètre crânien</strong> avec reconstitution des courbes</li>\n                <li>Hygiène (enfant et vêtements à sa taille ?), dénutrition / surcharge, mobilité</li>\n                <li>Inspection téguments : <span class=\"kw-clinique\">ecchymoses</span> / hématomes / plaies\n                  <ul>\n                    <li><strong>Photographies avec repère métrique</strong> + identité, consignées au dossier</li>\n                    <li><span class=\"kw-alerte\">Aspect « en forme »</span> ⚠️ évoque l’agent vulnérant</li>\n                    <li>Ne pas oublier <strong>face postérieure des oreilles</strong> et <strong>fesses</strong></li>\n                  </ul>\n                </li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Examen endo-buccal</strong></td>\n            <td>Hygiène, caries, soins dentaires → <span class=\"kw-clinique\">mauvais état bucco-dentaire</span> = <strong>marqueur le plus pertinent</strong> de la négligence</td>\n          </tr>\n          <tr>\n            <td><strong>Examen psychologique</strong></td>\n            <td>\n              <ul>\n                <li>Comportement (langage, attention, proximité, gestuelle)</li>\n                <li>Rechercher <span class=\"kw-clinique\">état dissociatif</span> (psychotraumatisme complexe)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Examen périnéal</strong></td>\n            <td>\n              <ul>\n                <li>Non systématique, <strong>de préférence par un médecin légiste</strong></li>\n                <li><strong>Accord du mineur</strong> respecté (refus respecté même sur demande judiciaire)</li>\n                <li>Petite fille : <span class=\"kw-clinique\">position de la grenouille</span> (DD, jambes fléchies, plantes des pieds se touchant) ± sonde de Foley à ballonnet</li>\n                <li>Examen anal : même position chez le petit ; DD jambes relevés chez l’adolescent</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Bilan <span class=\"kw-ttt\">biologique</span> « hors point d’appel »</h4>\n      <ul>\n        <li><strong><span class=\"kw-bio\">NFS</span>, bilan d’hémostase</strong></li>\n        <li>Bilan nutritionnel : <span class=\"kw-bio\">vitamines C, B9, B12, albumine</span></li>\n        <li>Screening toxicologique (sang, urines, cheveux) au cas par cas</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 47 — <span class=\"kw-def\">Suivi</span> d'un nourrisson, d'un enfant, d'un adolescent · 13 — Certificats médicaux</em></p>","frequence":2},{"id":"57-26","rang":"A","rubrique":"Prise en charge","titre":"Maltraitance et enfants en danger : connaître les modalités de l’orientation médicale et administrative","contenu":"<h4>Algorithme décisionnel — situation de danger diagnostiquée</h4>\n\n      <table >\n        <thead><tr><th>Question-clé</th><th>Réponse</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Suspicion de maltraitance grave ?</strong></td>\n            <td rowspan=\"4\">\n              <ul>\n                <li><strong>OUI</strong> à l’une des questions = <span class=\"kw-alerte\">situation d’urgence avérée</span></li>\n                <li>→ <strong>Orientation immédiate</strong> : <span class=\"kw-def\">signalement judiciaire</span> (Procureur) + <span class=\"kw-clinique\">prise en charge hospitalière en UAPED</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr><td><strong>Refus de soins urgents ?</strong></td></tr>\n          <tr><td><strong>Nécessité de protection urgente ?</strong></td></tr>\n          <tr><td><strong>Constat médico-légal urgent</strong> (infraction sexuelle &lt; 5 j) ?</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Situation non urgente mais nécessitant un avis</h4>\n      <ul>\n        <li>Ne pas rester seul face à la situation, <strong>demander l’avis</strong> :\n          <ul>\n            <li><strong>Médecin référent protection de l’enfance</strong> du Conseil départemental</li>\n            <li><strong>Service hospitalier référent</strong></li>\n            <li><strong>UAPED</strong> du secteur</li>\n          </ul>\n        </li>\n      </ul>\n\n      <h4>En cas de situation urgente</h4>\n\n      <table >\n        <thead><tr><th>Action</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-alerte\">Hospitalisation</span></strong></td>\n            <td>\n              <ul>\n                <li>Orienter vers une <span class=\"kw-clinique\">UAPED</span> en cas de :\n                  <ul>\n                    <li><span class=\"kw-alerte\">Danger immédiat</span> (lésions particulièrement graves, violences sexuelles alléguées)</li>\n                    <li>Risques encourus au domicile</li>\n                    <li><strong><span class=\"kw-alerte\">Urgence</span> médico-légale</strong> (prélèvements génétiques pour violences sexuelles &lt; 5 j)</li>\n                  </ul>\n                </li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Refus d’<span class=\"kw-alerte\">hospitalisation</span> + fugue des parents</strong></td>\n            <td><span class=\"kw-alerte\">Signalement judiciaire en urgence</span> par téléphone (<strong>Procureur</strong> ou à défaut <strong>commissariat / gendarmerie</strong>) puis par écrit</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>En dehors d’une <span class=\"kw-alerte\">urgence</span></h4>\n      <ul>\n        <li>Caractériser le <strong>danger</strong> et <span class=\"kw-clinique\">les</span> <strong>risques encourus</strong>, puis réaliser :\n          <ul>\n            <li>Soit <span class=\"kw-def\">Information préoccupante</span> (risque de danger, maltraitance, négligence) → <strong>CRIP</strong></li>\n            <li>Soit <span class=\"kw-def\">Signalement judiciaire</span> (danger immédiat) → <strong>Procureur</strong></li>\n          </ul>\n        </li>\n        <li>Peut solliciter le <strong>médecin référent protection de l’enfance</strong> du Conseil départemental ou le <strong>service hospitalier référent</strong></li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>UAPED — clé de voûte hospitalière.</strong> <span class=\"kw-clinique\">Les</span> <em>Unités d’Accueil Pédiatrique Enfant en Danger</em> regroupent des équipes pluridisciplinaires, sont référentes pour le repérage et le diagnostic des situations de maltraitance, et coordonnent les soins. Tout professionnel confronté à une situation de maltraitance peut joindre l’UAPED de son secteur.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 11 — Vilolence et santé · 12 — Violences sexuelles</em></p>","frequence":2},{"id":"57-27","rang":"A","rubrique":"Prise en charge","titre":"Maltraitance et enfants en danger : connaître les modalités de la prise en charge médicale","contenu":"<h4>Mesures urgentes en cas de traumatismes infligés</h4>\n      <ul>\n        <li><span class=\"kw-alerte\">Cotation de la douleur</span> et prise en charge thérapeutique → <strong>dans tous <span class=\"kw-clinique\">les</span> cas</strong></li>\n        <li>Lésions <strong>neurologiques</strong> : discussion d’un <span class=\"kw-clinique\">transfert en milieu neurochirurgical</span></li>\n        <li>Lésions <strong>orthopédiques</strong> : avis orthopédique sur site</li>\n        <li>Lésions <strong>tégumentaires</strong> : soins des plaies/brûlures + <span class=\"kw-ttt\">SAT-VAT</span> (sérum antitétanique + <span class=\"kw-ttt\">vaccination</span> si non à jour)</li>\n      </ul>\n\n      <h4>En cas de violences sexuelles</h4>\n\n      <table >\n        <thead><tr><th>Mesure</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">Contraception d’urgence</span></strong></td>\n            <td>Selon l’âge, si rapport <span class=\"kw-alerte\">&lt; 120 h</span> ⭐</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">Traitement antirétroviral</span></strong></td>\n            <td>Discussion selon nature de l’agression et délai entre agression et consultation</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Dépistage</span> / <span class=\"kw-def\">suivi</span> <span class=\"kw-clinique\">IST</span></strong></td>\n            <td>\n              <ul>\n                <li>Bilan initial : <span class=\"kw-clinique\">Gonocoque</span>, Chlamydia (urines, écouvillons vaginal/rectal/pharyngé) ; <span class=\"kw-bio\">sérologies</span> <span class=\"kw-etio\">VIH</span>, <span class=\"kw-clinique\">syphilis</span>, <span class=\"kw-etio\">VHB</span>, VHC</li>\n                <li>± mycoplasme, trichomonas selon contexte</li>\n                <li>À <strong>renouveler à<span class=\"kw-chiffre\"> 6 semaines</span> puis à<span class=\"kw-chiffre\"> 3 mois</span></strong></li>\n                <li><strong>β-hCG</strong> urinaire et plasmatique selon puberté</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Soutien et coordination</h4>\n      <ul>\n        <li>Soutien <strong>médico-psychologique</strong> pour l’enfant et sa famille</li>\n        <li>Organisation des <strong>soins d’aval</strong></li>\n        <li>Coordination assurée par <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">UAPED</span> (généralisation prévue dans tous les hôpitaux)</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 12 — Violences sexuelles</em></p>","frequence":0},{"id":"57-28","rang":"A","rubrique":"Prise en charge","titre":"Maltraitance et enfants en danger : connaître les modalités de la prise en charge médicolégale et administrative","contenu":"<div class=\"callout callout-warn\">\n        <strong>Objectif ultra-tombé (9 ⭐ bruts en QCM).</strong> Concentrer la relecture sur : <em>carnet de santé</em>, <em><span class=\"kw-bio\">CMI</span></em> (règles strictes), <em>IP <span class=\"kw-bio\">vs</span> <span class=\"kw-def\">signalement</span></em>, <em>OPP</em>, <em>circuit Procureur / juge des enfants</em>.\n      </div>\n\n      <h4>Carnet de santé — règles d’inscription</h4>\n      <ul>\n        <li>Tout <strong>constat de <span class=\"kw-clinique\">lésion</span></strong> doit y être <em>inscrit</em></li>\n        <li>Avec la <strong>date</strong></li>\n        <li><span class=\"kw-alerte\">SANS interprétation</span> ❌ (objectif : documenter une répétition de traumatismes)</li>\n      </ul>\n\n      <h4>Certificat médical initial (<span class=\"kw-bio\">CMI</span>) — règles de rédaction</h4>\n\n      <table >\n        <thead><tr><th>Item</th><th>Règle</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Indication</strong></td>\n            <td>Systématiquement rédigé devant tout constat de <span class=\"kw-clinique\">lésion</span></td>\n          </tr>\n          <tr>\n            <td><strong>Type</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-bio\">CMI</span> à la demande d’un tiers (hors réquisition)</li>\n                <li><span class=\"kw-bio\">CMI</span> sur réquisition judiciaire</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Contenu obl<span class=\"kw-chiffre\">iga</span>toire</strong></td>\n            <td>\n              <ul>\n                <li>Dates : rédaction, examen, faits allégués</li>\n                <li>Identités : rédacteur, enfant, accompagnants</li>\n                <li>ATCD <em>en lien avec <span class=\"kw-clinique\">les</span> faits</em> uniquement (les autres = secret médical) ⚠️</li>\n                <li>Recueil des commémoratifs au conditionnel ou entre guillemets</li>\n                <li>Description détaillée des lésions : <strong>type, forme, taille, couleur, localisation</strong></li>\n                <li>Examens complémentaires + résultats</li>\n                <li>Prise de photographies indiquée</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Interdictions ❌</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-alerte\">Identité de l’auteur présumé</span></li>\n                <li><span class=\"kw-alerte\">Datation des faits</span></li>\n                <li><span class=\"kw-alerte\">Imputabilité</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>ITT</strong></td>\n            <td>\n              <ul>\n                <li>Non obl<span class=\"kw-chiffre\">iga</span>toire en dehors d’un certificat descriptif sur réquisition</li>\n                <li>Si non habitué : « une éventuelle ITT sera à déterminer par un médecin spécialiste sur réquisition judiciaire »</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Conservation</strong></td>\n            <td><strong>Double conservé dans le dossier</strong> de l’enfant + éventuelles photographies</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Information préoccupante (IP) — contenu</h4>\n      <ul>\n        <li>Renseignements administratifs : nom, prénom, date de naissance, adresse(s), téléphone</li>\n        <li>Coordonnées du médecin</li>\n        <li>Éléments à l’origine de l’inquiétude</li>\n        <li><span class=\"kw-def\">Facteurs de risque</span> repérés</li>\n        <li>Propos de l’enfant et des accompagnants (entre guillemets, au conditionnel)</li>\n        <li>Données cliniques pertinentes</li>\n        <li>Comportement enfant / parents</li>\n        <li>Date, signature, tampon</li>\n      </ul>\n\n      <h4><span class=\"kw-def\">Signalement</span> judiciaire — suites possibles</h4>\n\n      <table >\n        <thead><tr><th>Étape</th><th>Action</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Procureur</strong></td>\n            <td>Renvoi au président du Conseil départemental ; enquête pénale éventuelle ; saisine du <strong>juge des enfants</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Juge des enfants — hors <span class=\"kw-alerte\">urgence</span></strong></td>\n            <td>\n              <ul>\n                <li><strong>AEMO</strong> (Assistance Éducative en Milieu Ouvert) — conseil/aide à la famille</li>\n                <li>Maintien dans la famille <strong>conditionné à des obl<span class=\"kw-chiffre\">iga</span>tions</strong> (établissements éducatifs...)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Juge des enfants — <span class=\"kw-alerte\">urgence</span></strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-alerte\">Placement</span> chez tiers, famille, service, foyer</li>\n                <li>Via <span class=\"kw-def\">OPP</span> (Ordonnance de Placement Provisoire) :\n                  <ul>\n                    <li>En <span class=\"kw-alerte\">urgence</span>, le <strong>Parquet</strong> peut ordonner une OPP avant la saisine du juge</li>\n                    <li>OPP <strong>motivée + notifiée</strong>, <span class=\"kw-alerte\">aucun recours possible</span></li>\n                    <li>Valable <span class=\"kw-chiffre\">8 jours</span></li>\n                  </ul>\n                </li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Mesures préventives (3 niveaux)</h4>\n      <ol>\n        <li><strong><span class=\"kw-def\">Prévention primaire</span></strong> — futurs parents : entretien médico-social du <span class=\"kw-clinique\">4ᵉ mois de grossesse</span>, campagnes prévention des secousses, info sur <span class=\"kw-clinique\">les</span> pleurs, accompagnement parentalité, <span class=\"kw-def\">dépistage</span> des FR, promotion de l’éducation non violente</li>\n        <li><strong><span class=\"kw-def\">Prévention secondaire</span></strong> — soignants : repérer <span class=\"kw-clinique\">les</span> situations, reconnaître la sémiologie, connaître les circuits IP / <span class=\"kw-def\">signalement</span></li>\n        <li><strong><span class=\"kw-def\">Prévention tertiaire</span></strong> — éviter <span class=\"kw-clinique\">les</span> récidives par mesures éducatives ± judiciaires, <span class=\"kw-def\">surveillance</span> prolongée pour prévenir les conséquences à long terme</li>\n      </ol>\n\n      <h4><span class=\"kw-def\">Suivi</span> prolongé</h4>\n      <ul>\n        <li>Coordination des structures : <span class=\"kw-clinique\">UAPED</span>, médecin traitant, <strong>PMI</strong> (&lt;<span class=\"kw-chiffre\"> 6 ans</span>), médecin référent Conseil départemental, <strong>ASE</strong> (Aide Sociale à l’Enfance), services judiciaires</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 13 — Certificats médicaux · 11 — Vilolence et santé · 12 — Violences sexuelles</em></p>","frequence":9},{"id":"57-29","rang":"A","rubrique":"Étiologie","titre":"Maltraitance et enfants en danger : savoir évoquer le diagnostic d’abus sexuel","contenu":"<div class=\"callout callout-info\">\n        <strong>Terminologie.</strong> Le terme « abus sexuel » (traduction de <em>sexual abuse</em>) <span class=\"kw-alerte\">n’est plus utilisé en France</span>. On parle de <strong>violences sexuelles</strong>, même si elles sont le plus souvent commises sans violence physique ou verbale mais par <em>intimidation, séduction, autorité</em>.\n      </div>\n\n      <h4>Circonstances diagnostiques</h4>\n      <ul>\n        <li>Enfant <strong>révèle spontanément</strong> des faits de nature sexuelle\n          <ul>\n            <li>Fausses allégations spontanées <em>très rares</em></li>\n            <li>Accueillir, <strong>ne pas questionner</strong>, ne pas douter d’emblée</li>\n          </ul>\n        </li>\n        <li>Enfant présente des <strong>anomalies de l’examen périnéal</strong></li>\n        <li>Entourage suspecte des faits du fait de :\n          <ul>\n            <li>Troubles du comportement</li>\n            <li>Conflits familiaux</li>\n            <li>Révélations après questionnements intrusifs</li>\n            <li><strong>Signes fonctionnels :</strong> énurésie, encoprésie, douleurs abdo, <span class=\"kw-clinique\">céphalées</span>, <span class=\"kw-clinique\">TCA</span>...</li>\n          </ul>\n        </li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Auteurs.</strong> <span class=\"kw-clinique\">Les</span> violences sexuelles sont <span class=\"kw-alerte\">le plus souvent commises au sein des familles</span> ou par des adultes qui connaissent l’enfant.\n      </div>\n\n      <h4>Selon l’âge</h4>\n\n      <table >\n        <thead><tr><th>Âge</th><th>Signes d’alerte</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Enfant jeune</strong></td>\n            <td>Être très préoccupé par des <strong>propos spontanés</strong> évoquant des faits de nature sexuelle subis</td>\n          </tr>\n          <tr>\n            <td><strong>Adolescent</strong></td>\n            <td>\n              <ul>\n                <li><strong>Auto-agressivité :</strong> scarifications, restriction alimentaire, dévalorisation, suicides/TS</li>\n                <li><strong>Hétéro-agressivité :</strong> violences agies (peuvent évoquer des violences subies)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Bilan diagnostique</h4>\n\n      <table >\n        <thead><tr><th>Axe</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Entretien</strong></td>\n            <td>\n              <ul>\n                <li>Mineur <strong>seul ou accompagné</strong> selon ses souhaits</li>\n                <li><span class=\"kw-alerte\">Pas de question fermée ou suggestive</span> ❌ (ne pas polluer la mémoire)</li>\n                <li>Questions <strong>ouvertes</strong> : « raconte-moi », « dis-moi en plus »</li>\n                <li>Vocabulaire adapté à l’âge</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Données à recueillir</strong></td>\n            <td>\n              <ul>\n                <li>Révélations, conditions, tiers présents, délai depuis <span class=\"kw-clinique\">les</span> faits, <span class=\"kw-def\">contact</span> persistant avec l’auteur</li>\n                <li><span class=\"kw-clinique\">Asthénie</span>, idées noires, sommeil/alimentation, scolarité, rapports avec pairs, intrafamiliaux, propreté, troubles du comportement, jeux sexuels, toxiques, contraception</li>\n                <li>Carnet de santé (ATCD, courbes)</li>\n                <li>Adolescents : <span class=\"kw-def\">stade</span> pubertaire, date des règles, rapports sexuels antérieurs/postérieurs, contraception</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Examen clinique</strong></td>\n            <td>\n              <ul>\n                <li>Global, avec accord du mineur : signes de violences + négligences (hygiène, bucco-dentaire)</li>\n                <li>Schéma + photographies (avec accord)</li>\n                <li><strong>Examen périnéal :</strong> uniquement si accepté + pertinent ; opérateur entraîné ; présence d’un tiers soignant rassurant</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Orientation</h4>\n      <ul>\n        <li>Référer à une équipe spécialisée <span class=\"kw-clinique\">UAPED</span></li>\n        <li>Prise en charge urgente si :\n          <ul>\n            <li>Nécessité de soins (<span class=\"kw-ttt\">ARV</span>, soins chir, pédopsychiatriques)</li>\n            <li>Protection vis-à-vis de l’auteur présumé</li>\n            <li><strong><span class=\"kw-alerte\">Urgence</span> médico-judiciaire</strong> (prélèvements / lésions traumatiques, classiquement &lt; <span class=\"kw-chiffre\">5 jours</span>)</li>\n          </ul>\n        </li>\n        <li>Hors <span class=\"kw-alerte\">urgence</span> : évaluation rapide et orientation en consultation pédiatrique spécialisée</li>\n      </ul>\n\n      <h4>Bilan <span class=\"kw-ttt\">biologique</span> en cas de suspicion de violences sexuelles</h4>\n      <ul>\n        <li><strong>β-hCG</strong> urinaire et plasmatique (selon puberté)</li>\n        <li><strong>Bilan <span class=\"kw-clinique\">IST</span> :</strong>\n          <ul>\n            <li><span class=\"kw-clinique\">Gonocoque</span>, Chlamydia (urines, écouvillons vaginal/rectal/pharyngé)</li>\n            <li><span class=\"kw-bio\">Sérologies</span> <span class=\"kw-etio\">VIH</span> 1 et 2, <span class=\"kw-clinique\">syphilis</span>, <span class=\"kw-etio\">VHB</span>, VHC</li>\n            <li>± mycoplasme, trichomonas</li>\n            <li>À renouveler à <strong><span class=\"kw-chiffre\">6 semaines</span></strong> puis <strong><span class=\"kw-chiffre\">3 mois</span></strong></li>\n          </ul>\n        </li>\n        <li><strong>Screening toxicologique</strong> (sang, urines, cheveux) au cas par cas</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 12 — Violences sexuelles · 11 — Vilolence et santé</em></p>","frequence":0},{"id":"57-30","rang":"A","rubrique":"Définition","titre":"Connaître les institutions de prise en charge : Protection maternelle et infantile","contenu":"<p>La <span class=\"kw-def\">Protection Maternelle et Infantile (PMI)</span> est un <strong>service départemental</strong> chargé d’assurer la protection sanitaire de la mère et de l’enfant. Elle joue un <em>rôle majeur</em> dans le repérage de la maltraitance.</p>\n\n      <table >\n        <thead><tr><th>Axe</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Tutelle</strong></td>\n            <td>Placée sous la responsabilité du <strong>président du Conseil départemental / général</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Liens</strong></td>\n            <td>Liens étroits / réseaux avec <span class=\"kw-clinique\">les</span> services hospitaliers de maternité et de pédiatrie</td>\n          </tr>\n          <tr>\n            <td><strong>Coordination</strong></td>\n            <td>Chaque service est coordonné par un <span class=\"kw-clinique\">médecin</span></td>\n          </tr>\n          <tr>\n            <td><strong>Équipe pluridisciplinaire</strong></td>\n            <td>\n              <ul>\n                <li><strong>Médecins</strong> (pédiatres, généralistes, gynécologues)</li>\n                <li><strong>Sages-femmes</strong> ++, <strong>puéricultrices</strong> ++</li>\n                <li>Assistantes sociales, éducateurs, psychologues, kinésithérapeutes</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Âge</strong></td>\n            <td>Concerne <span class=\"kw-clinique\">les</span> enfants de <span class=\"kw-alerte\">&lt; 6 ans</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Rôles (8 missions)</h4>\n      <ol>\n        <li><strong>Consultations / visites à domicile gratuites</strong> pour familles, nourrissons et femmes enceintes</li>\n        <li><strong>Mesures de prévention</strong> (médicale, psychologique, sociale, éducation à la santé)</li>\n        <li><span class=\"kw-clinique\">Actions de dépistage</span> (dont <span class=\"kw-clinique\">les</span> situations de maltraitance)</li>\n        <li>PEC des <strong>handicaps</strong> de l’enfant &lt;<span class=\"kw-chiffre\"> 6 ans</span> (orientation vers structures adéquates)</li>\n        <li><strong>Contrôle</strong> des établissements / services d’accueil &lt;<span class=\"kw-chiffre\"> 6 ans</span> + assistantes maternelles</li>\n        <li><strong><span class=\"kw-def\">Surveillance</span> médicale préventive</strong> à l’école maternelle (liaison fin de grande section / entrée au CP)</li>\n        <li><strong>Santé publique et <span class=\"kw-def\">surveillance</span> épidémiologique :</strong>\n          <ul>\n            <li>Avis de naissance</li>\n            <li>Certificats de santé obl<span class=\"kw-chiffre\">iga</span>toires : <strong>8ᵉ jour, 9ᵉ mois, 24ᵉ mois</strong></li>\n          </ul>\n        </li>\n        <li>Rôle <strong>éducatif</strong> auprès des familles, notamment en difficulté</li>\n      </ol>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 32 — Evaluation du nouveau-né · 47 — <span class=\"kw-def\">Suivi</span> d'un nourrisson, d'un enfant, d'un adolescent · 49 — Puberté · 53 — Retard de croissance staturo-pondéral</em></p>","frequence":0}],"astuces":[{"type":"danger","titre":"SBS = TDM + IRM + Fond d'œil + Body babygram + Signalement","contenu":"Devant toute suspicion de syndrome du bébé secoué : <strong>TDM cérébrale en urgence</strong>, complétée par <strong>IRM cérébrale et médullaire</strong>, <strong>fond d'œil par ophtalmologue &lt; 48 h</strong>, <strong>radiographies du squelette complet</strong> (body babygram), <strong>bilan biologique</strong> (hémostase) et <strong>signalement judiciaire systématique</strong>. Hospitalisation obligatoire, séparation protectrice de l'enfant."},{"type":"warn","titre":"Toute fracture chez l'enfant non marchant = suspicion de maltraitance","contenu":"Une fracture chez un enfant <strong>&lt; 1 an non-marchant</strong> doit être considérée comme suspecte jusqu'à preuve du contraire. Fractures hautement évocatrices : <strong>métaphysaires en coin/anse de seau</strong>, <strong>côtes postérieures</strong>, fractures multiples d'âges différents, fractures complexes du crâne."},{"type":"info","titre":"Signalement vs Information préoccupante : 2 voies, 2 destinataires","contenu":"<strong>Signalement judiciaire</strong> = au <strong>procureur</strong>, en cas de danger grave et imminent (violences, SBS, Silverman, viol). <strong>Information préoccupante</strong> = à la <strong>CRIP</strong> du département, en cas de suspicion sans urgence vitale. Les deux peuvent coexister. En cas de doute, signaler au procureur."},{"type":"danger","titre":"Protéger d'abord, comprendre ensuite","contenu":"Le médecin n'est pas un enquêteur, c'est un <strong>protecteur</strong>. En cas de doute : <strong>hospitaliser, signaler, conserver les éléments</strong>. Ne pas attendre la « preuve », ne pas confronter les parents, ne pas remettre l'enfant en cas de doute fort. Le signalement de bonne foi protège le médecin (article 226-14 CP)."},{"type":"warn","titre":"Révélation d'abus sexuel = signalement immédiat","contenu":"Toute révélation d'abus sexuel par un enfant doit être prise au sérieux (les fausses allégations sont &lt; 5 %). Ne pas induire de réponse, ne pas confronter à l'agresseur, hospitaliser, faire pratiquer un examen médico-légal &lt; 72 h, <strong>signaler au procureur sans délai</strong>, prescrire la prophylaxie post-exposition (VIH, IST, contraception d'urgence)."}],"strategie":{"urgence":"<p><strong>Traumatisme infligé suspecté <span class=\"q\">— SBS, <span class=\"kw-clinique\">lésion</span> sentinelle</span></strong></p><p><span class=\"kw-alerte\">mise à l'abri</span> + bilan paraclinique complet</p><ul><li>Toute suspicion de <span class=\"kw-def\">syndrome du bébé secoué</span> ou <span class=\"kw-clinique\">fracture chez un nourrisson non déambulant</span> → <span class=\"kw-alerte\">hospitalisation en urgence</span></li><li><span class=\"kw-clinique\">Fond d'œil</span> dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">&lt; 48 h</span> suivant le traumatisme</li></ul><p><strong>Violences sexuelles récentes <span class=\"q\">— <span class=\"kw-alerte\">urgence</span> médico-légale</span></strong></p><p>orientation vers une <span class=\"kw-clinique\">UAPED</span></p><ul><li>Faits <span class=\"kw-chiffre\">&lt; 5 jours</span> → examen sur <span class=\"kw-def\">réquisition judiciaire</span> par un <span class=\"kw-clinique\">médecin légiste</span> (prélèvements génétiques)</li><li><span class=\"kw-ttt\">Contraception d'urgence</span> si rapport <span class=\"kw-chiffre\">&lt; 120 h</span></li><li><span class=\"kw-ttt\">Traitement antirétroviral</span> discuté selon la nature de l'agression et le délai</li></ul><p><strong>Refus de soins + fugue parentale</strong></p><p>le <span class=\"kw-clinique\">Parquet</span> peut ordonner une <span class=\"kw-def\">OPP</span> en <span class=\"kw-alerte\">urgence</span> (<span class=\"kw-chiffre\">8 jours</span>, <span class=\"kw-alerte\">aucun recours</span>)</p><ul><li><span class=\"kw-alerte\">Signalement judiciaire en urgence</span> par téléphone (<span class=\"kw-clinique\">Procureur</span>, à défaut <span class=\"kw-clinique\">commissariat / gendarmerie</span>) puis confirmé par écrit</li></ul>","hospit":"<p><strong>Situation d'<span class=\"kw-alerte\">urgence</span> avérée <span class=\"q\">— OUI à une question</span></strong></p><p>orientation immédiate → <span class=\"kw-def\">signalement judiciaire</span> (<span class=\"kw-clinique\">Procureur</span>) + <span class=\"kw-alerte\">hospitalisation</span> en <span class=\"kw-clinique\">UAPED</span></p><ul><li><span class=\"kw-alerte\">Maltraitance grave</span>, <span class=\"kw-alerte\">refus de soins urgents</span>, <span class=\"kw-alerte\">protection urgente</span> ou <span class=\"kw-alerte\">constat médico-légal urgent</span> (infraction sexuelle <span class=\"kw-chiffre\">&lt; 5 j</span>)</li></ul><p><strong>Hors <span class=\"kw-alerte\">urgence</span> — caractériser le danger</strong></p><p>solliciter le <span class=\"kw-clinique\">médecin référent protection de l'enfance</span> du Conseil départemental ou le service hospitalier référent</p><ul><li><span class=\"kw-def\">Information préoccupante (IP)</span> → <span class=\"kw-clinique\">CRIP</span> si risque de danger, maltraitance ou négligence</li><li><span class=\"kw-def\">Signalement judiciaire</span> → <span class=\"kw-clinique\">Procureur</span> si danger immédiat</li></ul><p><strong>Deux systèmes de protection</strong></p><p><span class=\"kw-clinique\">UAPED</span> = clé de voûte hospitalière, joignable par tout professionnel</p><ul><li>Protection <strong>administrative</strong> : <span class=\"kw-clinique\">Conseil départemental</span> (chef de file) → <span class=\"kw-clinique\">CRIP</span></li><li>Protection <strong>judiciaire</strong> : <span class=\"kw-clinique\">Juge des enfants</span> + <span class=\"kw-clinique\">Procureur</span> (urgences, OPP)</li></ul>","redflags":"<ul><li><span class=\"kw-alerte\">Lésion traumatique avant l'âge de la marche</span> = traumatisme infligé jusqu'à preuve du contraire (<span class=\"kw-clinique\">lésion</span> sentinelle)</li><li><span class=\"kw-clinique\">Anamnèse absente, peu plausible ou incohérente</span> avec <span class=\"kw-clinique\">les</span> lésions ; <span class=\"kw-clinique\">délai</span> entre apparition des lésions et consultation</li><li><span class=\"kw-clinique\">Mise en cause d'un tiers</span> (jeune enfant, <span class=\"kw-clinique\">animal domestique</span>)</li><li><span class=\"kw-alerte\">≥ 15 ecchymoses</span> chez un enfant déambulant sans traumatisme ni trouble de l'hémostase</li><li><span class=\"kw-alerte\">Lésions « en forme »</span> (doigts, ceinture, câble électrique) évoquant l'agent vulnérant</li><li><span class=\"kw-clinique\">Ecchymoses</span> sur zones <span class=\"kw-clinique\">concaves ou protégées</span> (oreilles, joues, cou, tronc, fesses) ou d'<span class=\"kw-clinique\">âges différents</span></li><li>Triade SBS : <span class=\"kw-alerte\">HSD de la convexité</span> + <span class=\"kw-alerte\">hémorragies rétiniennes</span> + lésions <span class=\"kw-alerte\">hypoxo-anoxiques</span></li><li><span class=\"kw-alerte\">Suspicion de violences sexuelles</span> (impose un <span class=\"kw-def\">signalement</span>, d'autant plus rapide si faits récents)</li><li>Adolescent : <span class=\"kw-alerte\">tentative de suicide</span>, auto-agressivité, <span class=\"kw-clinique\">état dissociatif</span></li></ul>","principes":"<p>PEC <strong>double</strong> : <span class=\"kw-clinique\">médicale</span> (traiter <span class=\"kw-clinique\">les</span> lésions + antalgie systématique) ET <span class=\"kw-clinique\">médico-légale et administrative</span> (documenter sans interpréter, protéger l'enfant). Toute suspicion impose l'<span class=\"kw-alerte\">examen de l'intégralité de la fratrie</span>.</p><p><strong>PEC médicale des lésions</strong></p><ul><li><span class=\"kw-alerte\">Cotation de la douleur</span> et <span class=\"kw-ttt\">antalgie</span> dans tous <span class=\"kw-clinique\">les</span> cas</li><li>Lésions neurologiques → <span class=\"kw-ttt\">transfert en neurochirurgie</span> ; lésions orthopédiques → avis orthopédique</li><li>Lésions tégumentaires → soins des plaies / brûlures + <span class=\"kw-ttt\">SAT-VAT</span></li></ul><p><strong>Violences sexuelles</strong></p><ul><li><span class=\"kw-ttt\">Contraception d'urgence</span> si rapport <span class=\"kw-chiffre\">&lt; 120 h</span></li><li><span class=\"kw-ttt\">Traitement antirétroviral</span> discuté selon l'agression et le délai</li><li><span class=\"kw-def\">Dépistage</span> <span class=\"kw-bio\">IST</span> (<span class=\"kw-clinique\">Gonocoque</span>, Chlamydia, <span class=\"kw-bio\">sérologies</span> <span class=\"kw-etio\">VIH</span> / <span class=\"kw-clinique\">syphilis</span> / <span class=\"kw-etio\">VHB</span> / VHC) à renouveler à <span class=\"kw-chiffre\">6 semaines</span> puis <span class=\"kw-chiffre\">3 mois</span> ; <span class=\"kw-bio\">β-hCG</span> selon puberté</li></ul><p><strong>Documentation médico-légale</strong></p><p>photographies avec repère métrique + double conservé au dossier</p><ul><li><strong>Carnet de santé</strong> : inscrire tout constat de <span class=\"kw-clinique\">lésion</span> + date, <span class=\"kw-ci\">sans interprétation</span></li><li><span class=\"kw-def\">CMI</span> systématique : description détaillée (type, forme, taille, couleur, localisation), <span class=\"kw-ci\">sans identité de l'auteur</span>, <span class=\"kw-ci\">sans datation des faits</span>, <span class=\"kw-ci\">sans imputabilité</span></li></ul>","suivi":"<p><strong><span class=\"kw-def\">Suivi</span> prolongé & coordination</strong></p><ul><li><span class=\"kw-def\">Suivi</span> <span class=\"kw-alerte\">prolongé</span> pour prévenir <span class=\"kw-clinique\">les</span> conséquences somatiques, psychologiques et sociales</li><li>Coordination interdisciplinaire : <span class=\"kw-clinique\">UAPED</span>, médecin traitant, <span class=\"kw-clinique\">PMI</span> (&lt; <span class=\"kw-chiffre\">6 ans</span>), médecin référent Conseil départemental, <span class=\"kw-clinique\">ASE</span>, services judiciaires</li></ul><p><strong>Prévention (3 niveaux)</strong></p><ul><li><strong>Primaire</strong> (futurs parents) : entretien médico-social du <span class=\"kw-chiffre\">4ᵉ mois</span> de <span class=\"kw-ci\">grossesse</span>, campagnes de prévention des secousses, information sur <span class=\"kw-clinique\">les</span> pleurs, éducation non violente</li><li><strong>Secondaire</strong> (soignants) : repérer <span class=\"kw-clinique\">les</span> situations, reconnaître la sémiologie, connaître les circuits IP / <span class=\"kw-def\">signalement</span></li><li><strong>Tertiaire</strong> : éviter <span class=\"kw-clinique\">les</span> récidives (mesures éducatives ± judiciaires), <span class=\"kw-def\">surveillance</span> prolongée</li></ul>"},"liensGlobaux":[{"href":"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/enfant-vulnerable-genetique/maltraitance","label":"Collège Pédiatrie — Maltraitance"}],"cards":[{"i":"1230acdbd37a","n":57,"o":"57-1","u":"Définition","t":"Nourrisson : connaître la définition du syndrome du bébé secoué","q":"Quelles sont les caractéristiques cinétiques du syndrome du bébé secoué (SBS) ?","a":"<p>Il s'agit d'un traumatisme à <strong>haute cinétique</strong>, comparable en violence à un accident de la voie publique.</p>"},{"i":"54ce1b87755a","n":57,"o":"57-1","u":"Définition","t":"Nourrisson : connaître la définition du syndrome du bébé secoué","q":"Quelle est la définition du syndrome du bébé secoué (SBS) chez le nourrisson ?","a":"<p>Le syndrome du bébé secoué est un sous-ensemble des <strong>traumatismes crâniens infligés</strong>, où le <strong>secouement</strong> (seul ou associé à un impact) est la cause du traumatisme crânien.</p>"},{"i":"ebd96aec5844","n":57,"o":"57-1","u":"Définition","t":"Nourrisson : connaître la définition du syndrome du bébé secoué","q":"Chez quel terrain le syndrome du bébé secoué (SBS) survient-il majoritairement ?","a":"<p>Il survient la plupart du temps chez un <strong>nourrisson de moins de 1 an</strong>.</p>"},{"i":"09816caa7eb6","n":57,"o":"57-10","u":"Diagnostic positif","t":"Nourrisson, enfant : savoir évoquer un syndrome de Silverman","q":"Quelle est la 'règle d'or' concernant la découverte de lésions osseuses fortuites chez un nourrisson et le risque de traumatisme infligé ?","a":"<p>Plus la découverte de lésion osseuse est <strong>fortuite</strong> (c'est-à-dire une radiographie faite pour une autre raison et sans contexte traumatique rapporté), plus le <strong>risque de traumatisme infligé est élevé</strong>.</p>"},{"i":"4beb00179b95","n":57,"o":"57-10","u":"Diagnostic positif","t":"Nourrisson, enfant : savoir évoquer un syndrome de Silverman","q":"Dans quelle situation clinique doit-on évoquer un syndrome de Silverman et conduire à une hospitalisation chez un nourrisson ?","a":"<p>Toute <strong>fracture chez un nourrisson qui ne se déplace pas</strong> ou qui survient <strong>sans traumatisme particulier rapporté</strong> doit conduire à une hospitalisation pour un bilan exhaustif, car elle peut être une <strong>lésion sentinelle</strong> avant l’âge de la marche.</p>"},{"i":"8f54aecb6541","n":57,"o":"57-10","u":"Diagnostic positif","t":"Nourrisson, enfant : savoir évoquer un syndrome de Silverman","q":"Quelles sont les lésions osseuses les plus évocatrices de traumatismes infligés chez un nourrisson dans le cadre d'un syndrome de Silverman ?","a":"<ul><li>Les <strong>fractures diaphysaires</strong>, qu'elles soient récentes ou anciennes (avec la présence de cals osseux).</li><li>Les <strong>lésions métaphysaires</strong>, se présentant comme des arrachements en coin ou en « anse de seau », suggérant des mécanismes de traction ou de torsion.</li><li>Les <strong>lésions périostées</strong>, telles que les décollements du périoste, qui sont également évocatrices de mécanismes de torsion.</li></ul>"},{"i":"910a0940c5aa","n":57,"o":"57-10","u":"Diagnostic positif","t":"Nourrisson, enfant : savoir évoquer un syndrome de Silverman","q":"Comment définit-on le syndrome de Silverman sur le plan radiologique chez un nourrisson ?","a":"<p>Le syndrome de Silverman se caractérise par la découverte radiologique de <strong>lésions osseuses d’âges différents</strong>, en lien avec des <strong>traumatismes infligés</strong> et sans expression clinique initialement repérée.</p>"},{"i":"665ddc2acd17","n":57,"o":"57-11","u":"Définition","t":"Nourrisson, enfant : connaître la définition du syndrome de Silverman","q":"Comment évaluer le risque de traumatisme infligé en cas de syndrome de Silverman ?","a":"<p>Plus la découverte fortuite de ces lésions est grande, plus le <strong>risque de traumatisme infligé est élevé</strong>.</p>"},{"i":"cf1e3c5238b9","n":57,"o":"57-11","u":"Définition","t":"Nourrisson, enfant : connaître la définition du syndrome de Silverman","q":"Quelle est la spécificité d'âge du syndrome de Silverman ?","a":"<p>Le syndrome de Silverman est décrit spécifiquement chez le <strong>nourrisson</strong>. Chez l’enfant plus grand, des fractures multiples d’âges différents entrent dans le cadre plus large de la maltraitance physique.</p>"},{"i":"e1b383f5e307","n":57,"o":"57-11","u":"Définition","t":"Nourrisson, enfant : connaître la définition du syndrome de Silverman","q":"Quelle est la définition radiologique du syndrome de Silverman chez le nourrisson ?","a":"<p>Le syndrome de Silverman est caractérisé par la découverte radiologique de <strong>lésions osseuses d’âges différents</strong> chez un nourrisson, en lien avec des traumatismes infligés et sans expression clinique repérée.</p>"},{"i":"e545d9287707","n":57,"o":"57-11","u":"Définition","t":"Nourrisson, enfant : connaître la définition du syndrome de Silverman","q":"Quel aspect du diagnostic est essentiel dans le syndrome de Silverman ?","a":"<p>Le <strong>diagnostic est radiologique</strong> et non clinique. Les lésions peuvent avoir déjà guéri ou évoluer sans symptôme apparent.</p>"},{"i":"14c944703cef","n":57,"o":"57-12","u":"Diagnostic positif","t":"Nourrisson, enfant : connaître la conduite diagnostique en cas de suspicion de syndrome de Silverman","q":"Quel bilan biologique doit être réalisé en cas de lésions osseuses dans le cadre d'une suspicion de syndrome de Silverman, et quel est son objectif principal ?","a":"<p>Le bilan biologique est réalisé devant les lésions osseuses et vise principalement à éliminer d'autres causes, notamment le rachitisme. Il comprend :</p><ul><li><strong>Biologie sanguine</strong> : NFS, VS, CRP, bilan hépatique (PAL), bilan rénal (créatinine), ionogramme sanguin.</li><li><strong>Bilan phosphocalcique</strong> : calcémie, phosphorémie, PTH, vitamine D.</li><li><strong>Biologie urinaire</strong> : ionogramme urinaire, créatininurie, protéinurie 24h, calciurie 24h, phosphaturie 24h, taux de réabsorption tubulaire du phosphore.</li></ul>"},{"i":"360611758140","n":57,"o":"57-12","u":"Diagnostic positif","t":"Nourrisson, enfant : connaître la conduite diagnostique en cas de suspicion de syndrome de Silverman","q":"Quelle est la première étape diagnostique en cas de suspicion de syndrome de Silverman et quel en est le critère déclencheur majeur chez le nourrisson ?","a":"<p>La première étape est l'<strong>hospitalisation systématique</strong>. Le critère déclencheur majeur, imposant cette hospitalisation, est la survenue d'une fracture chez un <strong>nourrisson non déambulant</strong> ou <strong>sans traumatisme rapporté</strong>.</p>"},{"i":"661f53fcb006","n":57,"o":"57-12","u":"Diagnostic positif","t":"Nourrisson, enfant : connaître la conduite diagnostique en cas de suspicion de syndrome de Silverman","q":"Quelles sont les démarches médico-légales et sociales à entreprendre en cas de suspicion de maltraitance chez un enfant ?","a":"<p>Les démarches médico-légales et sociales sont conjointes et comprennent :</p><ul><li>Un <strong>Certificat Médical Initial (CMI)</strong> systématique, décrivant les lésions <strong>sans interprétation</strong> sur l'origine.</li><li>Une information préoccupante (<strong>IP</strong>) au <strong>CRIP</strong> (Cellule de Recueil des Informations Préoccupantes) ou un <strong>signalement judiciaire</strong> direct, selon l'urgence et le niveau de danger.</li><li>L'<strong>hospitalisation</strong> en Unité d'Accueil Pédiatrique Enfants en Danger (<strong>UAPED</strong>) si disponible.</li><li>L'<strong>examen systématique de la fratrie</strong> de l'enfant.</p>"},{"i":"b08957ab5130","n":57,"o":"57-12","u":"Diagnostic positif","t":"Nourrisson, enfant : connaître la conduite diagnostique en cas de suspicion de syndrome de Silverman","q":"Quels sont les examens d'imagerie clés à réaliser dans le bilan de suspicion de syndrome de Silverman, et quelle est l'approche spécifique chez l'enfant de moins de 2 ans ?","a":"<p>Les examens d'imagerie clés sont :</p><ul><li>Une <strong>radiographie du squelette complet</strong>, avec un protocole d'analyse segment par segment, relue par <strong>deux radiologues pédiatres</strong>. Elle est systématique chez l'enfant de <strong>moins de 2 ans</strong>.</li><li>En cas de bilan douteux ou de forte suspicion, une <strong>scintigraphie osseuse</strong> ou une <strong>radiographie de contrôle à 10 jours</strong> est indiquée pour objectiver des lésions passées inaperçues.</li><li>Un <strong>scanner cérébral</strong> et une <strong>IRM cérébrale et médullaire</strong> pour rechercher des lésions associées, notamment dans le cadre d'un <emp>Shaken Baby Syndrome</emp> (SBS).</li><li>Une <strong>échographie abdominale</strong> pour détecter des lésions profondes.</li><li>Un examen du <strong>fond d'œil</strong> (FO) pour rechercher des hémorragies rétiniennes.</li></ul>"},{"i":"5479faec8188","n":57,"o":"57-13","u":"Diagnostic positif","t":"Nourrisson, enfant : connaître les lésions associées au syndrome de Silverman","q":"Quelles sont les caractéristiques des décollements épiphysaires associés au syndrome de Silverman ?","a":"<p>Les décollements épiphysaires sont observés au niveau de l'<strong>humérus distal et proximal</strong> ainsi qu'au niveau du <strong>fémur</strong>.</p>"},{"i":"7a6b1de151c3","n":57,"o":"57-13","u":"Diagnostic positif","t":"Nourrisson, enfant : connaître les lésions associées au syndrome de Silverman","q":"Quelles sont les caractéristiques des fractures diaphysaires dans le syndrome de Silverman ?","a":"<p>Les fractures diaphysaires peuvent être de deux types :</p><ul><li>Un <strong>trait transverse</strong> en cas de coup direct.</li><li>Un <strong>trait oblique ou spiroïde</strong> en cas de torsion.</li></ul>"},{"i":"87b3e323d300","n":57,"o":"57-13","u":"Diagnostic positif","t":"Nourrisson, enfant : connaître les lésions associées au syndrome de Silverman","q":"Quelles sont les caractéristiques des fractures métaphysaires dans le cadre du syndrome de Silverman ?","a":"<p>Les fractures métaphysaires sont des <strong>petits arrachements osseux</strong>. Elles sont typiquement causées par des gestes de traction et de torsion et peuvent prendre l'aspect d'un <strong>coin</strong> ou d'une « <strong>anse de seau</strong> ».</p>"},{"i":"a6d60d20465b","n":57,"o":"57-13","u":"Diagnostic positif","t":"Nourrisson, enfant : connaître les lésions associées au syndrome de Silverman","q":"Quelle est la signature radiologique caractéristique du syndrome de Silverman ?","a":"<p>La signature radiologique du syndrome de Silverman est la coexistence de <strong>lésions récentes</strong> (avec un trait fin) et de <strong>lésions anciennes</strong> (avec des cals osseux). Cette présentation « <strong>plurifocale et d’âges différents</strong> » est incompatible avec un événement traumatique unique tel que rapporté.</p>"},{"i":"d72945c768d7","n":57,"o":"57-13","u":"Diagnostic positif","t":"Nourrisson, enfant : connaître les lésions associées au syndrome de Silverman","q":"Comment les cals osseux peuvent-ils orienter vers un syndrome de Silverman ?","a":"<p>Les <strong>cals osseux</strong> sont des marqueurs de <strong>fractures anciennes</strong> qui n'ont pas été rapportées par les parents. Leur présence, associée à d'autres lésions, est un indicateur de traumatismes répétés.</p>"},{"i":"de75a4407cc1","n":57,"o":"57-13","u":"Diagnostic positif","t":"Nourrisson, enfant : connaître les lésions associées au syndrome de Silverman","q":"Quelles sont les caractéristiques des fractures costales dans le syndrome de Silverman chez le nourrisson ou l'enfant ?","a":"<p>Dans le syndrome de Silverman, les fractures des côtes sont fréquemment localisées sur les <strong>arcs moyens ou postérieurs</strong>. Elles résultent d'un mécanisme de compression thoracique, tel que le fait de serrer fortement ou de secouer le bébé.</p>"},{"i":"0e28a390562e","n":57,"o":"57-17","u":"Définition","t":"Enfant, adolescent : connaître la définition de la maltraitance","q":"Quelle est la nuance entre un enfant \"maltraité\" et un enfant \"en risque\" ?","a":"<p>Un enfant <strong>\"maltraité\"</strong> est victime d'actes avérés de maltraitance. Un enfant <strong>\"en risque\"</strong> n'est pas à proprement parler déjà maltraité, mais ses conditions d'existence risquent de mettre en danger sa santé, sa sécurité, sa moralité, son éducation ou la qualité des réponses à ses besoins quotidiens.</p>"},{"i":"4a284c83bf41","n":57,"o":"57-17","u":"Définition","t":"Enfant, adolescent : connaître la définition de la maltraitance","q":"Selon l'OMS, quelle est la définition générale de la maltraitance chez l'enfant ?","a":"<p>La maltraitance de l'enfant, selon l'OMS, est définie comme toutes les formes de mauvais traitements <strong>physiques, affectifs, sévices sexuels, négligence, exploitation</strong> commerciale ou autre, entraînant un préjudice réel ou potentiel pour la <strong>santé, la survie, le développement ou la dignité</strong> de l'enfant, dans le contexte d'une relation de responsabilité, de confiance ou de pouvoir.</p>"},{"i":"88c20ee4e937","n":57,"o":"57-17","u":"Définition","t":"Enfant, adolescent : connaître la définition de la maltraitance","q":"Quels sont les différents types d'actes de maltraitance par \"commission\" ?","a":"<ul><li><strong>Physiques</strong>: Coups, claques, corrections.</li><li><strong>Sexuelles</strong>: Toute participation d'un enfant à des activités sexuelles inappropriées à son âge et à son développement psychosexuel, subies sous contrainte, violence, séduction, ou transgressant les tabous sociaux.</li><li><strong>Psychologiques</strong>: Dénigrement, humiliation, injonction paradoxale, rejet affectif, punition ou exigence éducative inadaptée à l'âge ou aux possibilités de l'enfant.</li><li><strong>Conjugales</strong>: Exposition d'un enfant à des violences entre partenaires intimes.</li><li><strong>Cyberviolences</strong>: Exposition à images violentes/pornographiques, sexting, happy slapping, cyber-harcèlement.</li><li><strong>Institutionnelles</strong>: Violences subies hors famille, en milieu collectif ou cachées par les institutions d'accueil.</li></ul>"},{"i":"9621a237bad8","n":57,"o":"57-17","u":"Définition","t":"Enfant, adolescent : connaître la définition de la maltraitance","q":"Quelle est la définition de la maltraitance par \"omission\" ?","a":"<p>La maltraitance par \"omission\" correspond à la <strong>négligence</strong>, c'est-à-dire l'absence de réponse aux <strong>besoins fondamentaux</strong> de l'enfant (sécurité, santé, scolarité, mise en collectivité).</p>"},{"i":"1a4782f13437","n":57,"o":"57-18","u":"Identifier une urgence","t":"Enfant, adolescent : savoir reconnaître une situation évoquant une maltraitance","q":"Quelle est la définition et la signification d'une 'lésion sentinelle' dans le contexte de la maltraitance infantile ?","a":"<p>Une <strong>lésion sentinelle</strong> est toute <strong>lésion d'allure traumatique</strong> observée chez un enfant <strong>avant l'âge de la marche</strong>. Elle doit être considérée comme un <strong>traumatisme infligé jusqu'à preuve du contraire</strong>.</p>"},{"i":"5f95f4751025","n":57,"o":"57-18","u":"Identifier une urgence","t":"Enfant, adolescent : savoir reconnaître une situation évoquant une maltraitance","q":"Quels sont les principaux signes d'alerte anamnestiques pouvant évoquer une maltraitance chez l'enfant ?","a":"<ul><li><strong>Absence d'explication</strong> ou caractère peu plausible / incohérent des lésions.</li><li>Délai important entre l'apparition des lésions et la consultation (fort indicateur de <strong>négligence</strong>).</li><li><strong>Mise en cause d'un tiers</strong> (notamment un jeune enfant ou un animal domestique).</li><li>Présence de <strong>facteurs de risque de maltraitance</strong>.</li><li>Consultations répétées pour traumatismes / accidents domestiques.</li><li>Consultations répétées pour plaintes somatiques sans étiologie (douleurs abdominales, céphalées, troubles du sommeil/alimentation).</li></ul>"},{"i":"63f16626f725","n":57,"o":"57-18","u":"Identifier une urgence","t":"Enfant, adolescent : savoir reconnaître une situation évoquant une maltraitance","q":"Quels sont les signes cliniques et comportementaux pouvant orienter vers une maltraitance chez les enfants plus âgés et les adolescents ?","a":"<ul><li>Signes de <strong>TSPT</strong> (trouble de stress post-traumatique), trouble dépressif, trouble psychoaffectif.</li><li>Tentative de suicide, <strong>auto-agressivité</strong> (scarifications, restriction alimentaire).</li><li><strong>Hétéro-agressivité</strong> (violences agies pouvant refléter des violences subies).</li><li><strong>Désinsertion sociale</strong>, fugues, conduites à risque.</li><li>Chute des résultats scolaires ou surinvestissement scolaire.</li></ul>"},{"i":"65d6b590b688","n":57,"o":"57-18","u":"Identifier une urgence","t":"Enfant, adolescent : savoir reconnaître une situation évoquant une maltraitance","q":"Quelles sont les caractéristiques des lésions physiques les plus fréquentes, leur localisation et les lésions profondes associées en cas de maltraitance ?","a":"<ul><li>Les lésions élémentaires les plus fréquentes sont les <strong>ecchymoses</strong> et les <strong>hématomes</strong>.</li><li>Les localisations les plus fréquentes sont le <strong>visage (75%)</strong>, le tronc (30%) et les extrémités (25%).</li><li>Des <strong>lésions profondes</strong> (osseuses, abdominales, neurologiques) sont associées dans <strong>plus de 50% des cas</strong>.</li></ul>"},{"i":"8e0bd2aa4d99","n":57,"o":"57-18","u":"Identifier une urgence","t":"Enfant, adolescent : savoir reconnaître une situation évoquant une maltraitance","q":"Face à une suspicion de maltraitance chez un enfant, quelle est la conduite à tenir systématique concernant la fratrie ?","a":"<p>En cas de suspicion de maltraitance chez un enfant, l'<strong>intégralité de la fratrie doit être examinée</strong>.</p>"},{"i":"08328d8e556d","n":57,"o":"57-19","u":"Diagnostic positif","t":"Enfant, adolescent : identifier les lésions traumatiques élémentaires dans la maltraitance","q":"Quels éléments concernant le nombre et la taille des ecchymoses doivent faire suspecter une maltraitance chez l'enfant ?","a":"<ul><li>Un <strong>nombre supérieur ou égal à 15 lésions cutanées</strong> chez un enfant déambulant, sans traumatisme accidentel ou pathologie de l'hémostase connue, doit faire suspecter une maltraitance.</li><li>Des ecchymoses de <strong>tailles différentes</strong> ou de <strong>colorations différentes</strong> (jaune, vert, violet, rouge) évoquant des âges différents, ainsi que des <strong>ecchymoses de grande taille</strong>, sont également suspectes.</li></ul>"},{"i":"0b791fb662e5","n":57,"o":"57-19","u":"Diagnostic positif","t":"Enfant, adolescent : identifier les lésions traumatiques élémentaires dans la maltraitance","q":"Quelles sont les caractéristiques des ecchymoses suspectes de maltraitance chez l'enfant liées à leur forme ?","a":"<p>Des ecchymoses ayant une <strong>forme évocatrice de l'objet traumatisant</strong> (c'est-à-dire « en forme de ») sont suspectes de maltraitance. Cela inclut des marques prenant la forme de doigts, de mains, d'une ceinture, d'un bâton ou d'un câble électrique.</p>"},{"i":"1e8e385f13b3","n":57,"o":"57-19","u":"Diagnostic positif","t":"Enfant, adolescent : identifier les lésions traumatiques élémentaires dans la maltraitance","q":"Quelles localisations d'ecchymoses sont fortement évocatrices de maltraitance chez l'enfant ?","a":"<ul><li>Les <strong>zones concaves</strong> : oreilles, joues, cou.</li><li>Les <strong>zones habituellement non exposées</strong> et protégées par les vêtements : tronc, faces internes des bras et des cuisses, faces postérieures des cuisses, fesses.</li></ul>"},{"i":"63dc91229df6","n":57,"o":"57-19","u":"Diagnostic positif","t":"Enfant, adolescent : identifier les lésions traumatiques élémentaires dans la maltraitance","q":"Quelles sont les caractéristiques des brûlures suspectes de maltraitance chez l'enfant ?","a":"<ul><li>Des <strong>bords nets</strong> évoquant une immersion (« en chaussettes », « en gants »).</li><li>Une <strong>forme caractéristique</strong> (ex: en forme de cigarette).</li><li>Des localisations sur des <strong>zones normalement protégées</strong> par les vêtements (fesses, périnée).</li></ul>"},{"i":"ccc1095aadd7","n":57,"o":"57-19","u":"Diagnostic positif","t":"Enfant, adolescent : identifier les lésions traumatiques élémentaires dans la maltraitance","q":"Comment identifier des morsures suspectes de maltraitance chez l'enfant ?","a":"<p>Il faut rechercher des <strong>marques circulaires ou ovales de 2 à 5 cm</strong>, généralement formées de <strong>deux arcs concaves opposés</strong>, parfois associées à une ecchymose centrale.</p>"},{"i":"df1ba66c5dfd","n":57,"o":"57-19","u":"Diagnostic positif","t":"Enfant, adolescent : identifier les lésions traumatiques élémentaires dans la maltraitance","q":"Quelles sont les règles pratiques essentielles lors de l'examen tégumentaire d'un enfant suspect de maltraitance pour la documentation des lésions ?","a":"<ul><li>Toutes les lésions doivent être <strong>photographiées avec un repère métrique</strong> et l'identité de l'enfant.</li><li>Ces lésions doivent être <strong>consignées précisément dans le dossier médical</strong>.</li><li>L'examen doit être <strong>exhaustif</strong>, en n'oubliant pas la face postérieure des oreilles, les fesses et le périnée.</li><li>Des <strong>schémas</strong> doivent être réalisés dans le dossier pour détailler la taille, la forme, la couleur et la localisation des lésions.</li></ul>"},{"i":"fa42d70b3b43","n":57,"o":"57-19","u":"Diagnostic positif","t":"Enfant, adolescent : identifier les lésions traumatiques élémentaires dans la maltraitance","q":"Quelles abrasions doivent faire suspecter une maltraitance chez l'enfant ?","a":"<p>Les abrasions siégeant aux <strong>poignets et aux chevilles</strong> sont particulièrement suspectes, pouvant évoquer une contention par des liens.</p>"},{"i":"522b2a87c026","n":57,"o":"57-21","u":"Définition","t":"Nourrisson, enfant, adolescent : connaître la définition du signalement judiciaire, administratif et de la CRIP","q":"Quelle est la définition d'une Information Préoccupante (IP) dans le contexte de la protection de l'enfance ?","a":"<p>L'Information Préoccupante (IP) est tout élément d’information, y compris médical, susceptible de laisser craindre qu’un enfant se trouve en situation de danger ou de risque de danger, et qu'il puisse avoir besoin d’une aide.</p>"},{"i":"bb979c2e3ca4","n":57,"o":"57-21","u":"Définition","t":"Nourrisson, enfant, adolescent : connaître la définition du signalement judiciaire, administratif et de la CRIP","q":"Quel est le rôle de la Cellule de Recueil des Informations Préoccupantes (CRIP) ?","a":"<p>La CRIP est une cellule départementale dépendant du <strong>Conseil départemental</strong>. Elle a pour rôle de centraliser toutes les Informations Préoccupantes (IP), d'évaluer de manière pluridisciplinaire la situation du mineur (dans un délai de <strong>3 mois</strong>) et de prendre des décisions telles que le <strong>signalement judiciaire</strong>, le classement sans suite, ou l'orientation vers une <strong>intervention administrative</strong>.</p>"},{"i":"db7061c3b124","n":57,"o":"57-21","u":"Définition","t":"Nourrisson, enfant, adolescent : connaître la définition du signalement judiciaire, administratif et de la CRIP","q":"Qu'est-ce qu'un signalement judiciaire en protection de l'enfance et dans quels cas est-il indiqué ?","a":"<p>Un signalement judiciaire est un écrit objectif portant à la connaissance du <strong>Procureur de la République</strong> la situation d’un mineur présumé en danger, constituant une dérogation au secret professionnel. Il est indiqué en cas de <strong>maltraitance grave</strong>, lorsqu'une <strong>protection immédiate de l'enfant</strong> est nécessaire ou qu'une <strong>enquête pénale</strong> (contexte délictuel ou criminel) est requise.</p>"},{"i":"0b7dce2d4f00","n":57,"o":"57-24","u":"Épidémiologie","t":"Maltraitance et enfants en danger : connaître l’épidémiologie","q":"Quel est le nombre estimé de décès intrafamiliaux d'enfants en 2020 et l'incidence du Syndrome du Bébé Secoué (SBS) en France ?","a":"<p>En 2020, <strong>49 enfants</strong> sont décédés dans le cadre intrafamilial. Concernant le Syndrome du Bébé Secoué (SBS), l'incidence en France est d'environ <strong>200 enfants victimes par an</strong>.</p>"},{"i":"2d2171aa651e","n":57,"o":"57-24","u":"Épidémiologie","t":"Maltraitance et enfants en danger : connaître l’épidémiologie","q":"Combien de mineurs étaient sous protection de l'enfance en France au 31 décembre 2020 ?","a":"<p>Au 31 décembre 2020, <strong>308 000 mineurs</strong> en France (hors Mayotte) bénéficiaient d'au moins une prestation ou mesure du dispositif de protection de l'enfance, soit <strong>21,4 pour 1 000 mineurs</strong>.</p>"},{"i":"68fa77a2589c","n":57,"o":"57-24","u":"Épidémiologie","t":"Maltraitance et enfants en danger : connaître l’épidémiologie","q":"Quelle est la principale difficulté concernant l'épidémiologie française de la maltraitance des enfants ?","a":"<p>La principale difficulté est le manque de précision dû à l'<strong>absence d'homogénéité des données statistiques</strong> et le fait que les évaluations sont souvent anciennes. Les chiffres officiels sous-estiment la réalité en raison d'une <strong>sous-déclaration majeure</strong>.</p>"},{"i":"d183e1ef6394","n":57,"o":"57-24","u":"Épidémiologie","t":"Maltraitance et enfants en danger : connaître l’épidémiologie","q":"Pourquoi le repérage des situations de maltraitance infantile est-il un enjeu de santé publique, et quel est le rôle du médecin de premier recours ?","a":"<p>Le repérage est un enjeu de santé publique en raison de la <strong>fréquence</strong> des situations (plus d'un enfant sur dix concerné en pédiatrie) et de la <strong>sous-déclaration majeure</strong>. Tout médecin de premier recours doit savoir <strong>repérer une situation à risque</strong> et <strong>activer le circuit d'information préoccupante (IP) ou de signalement</strong>.</p>"},{"i":"01bdc647cf99","n":57,"o":"57-25","u":"Diagnostic positif / Examen C","t":"Maltraitance et enfants en danger : connaître les modalités de l’enquête clinique","q":"Quel bilan biologique peut être envisagé au cas par cas chez un enfant en danger ou maltraité, en dehors d'un point d'appel spécifique ?","a":"<p>Au cas par cas, on peut envisager :</p><ul><li>Une <strong>NFS</strong> (Numération Formule Sanguine) et un <strong>bilan d'hémostase</strong>.</li><li>Un <strong>bilan nutritionnel</strong> (vitamines C, B9, B12, albumine).</li><li>Un <strong>screening toxicologique</strong> (sang, urines, cheveux).</li></ul>"},{"i":"4739013b3d22","n":57,"o":"57-25","u":"Diagnostic positif / Examen C","t":"Maltraitance et enfants en danger : connaître les modalités de l’enquête clinique","q":"Lors de l'enquête clinique face à une suspicion de maltraitance et enfants en danger, quels sont les 3 axes majeurs de réponse à évaluer ?","a":"<p>Les 3 axes majeurs de réponse sont :</p><ul><li>Évaluer la nécessité et l'urgence de <strong>soins pour l'enfant</strong> (antalgiques, paracliniques, accompagnements).</li><li><strong>Consigner de manière exhaustive</strong> dans le dossier médical toutes les observations (circonstances, données cliniques, présentation générale de l'enfant).</li><li>Vérifier si la <strong>protection du mineur est assurée</strong>, et si nécessaire, envisager une hospitalisation pour mise à l'abri et recueil de la parole.</li></ul>"},{"i":"5e834a2c2e61","n":57,"o":"57-25","u":"Diagnostic positif / Examen C","t":"Maltraitance et enfants en danger : connaître les modalités de l’enquête clinique","q":"Quel est l'outil indispensable à consulter précocement lors de l'examen d'un enfant en danger ou suspecté de maltraitance ?","a":"<p>Le <strong>carnet de santé</strong> est l'outil indispensable. Il permet de retracer :</p><ul><li>La situation périnatale.</li><li>La qualité du suivi médical.</li><li>Le développement psychoaffectif.</li><li>Les vaccinations.</li><li>Les courbes staturo-pondérales.</li><li>L'existence de handicap ou de maladie chronique.</li></ul>"},{"i":"6f4a917562d9","n":57,"o":"57-25","u":"Diagnostic positif / Examen C","t":"Maltraitance et enfants en danger : connaître les modalités de l’enquête clinique","q":"Quelles sont les modalités à respecter pour l'examen périnéal lors de la prise en charge d'un enfant suspecté de maltraitance ?","a":"<p>L'examen périnéal n'est <strong>pas systématique</strong> et doit être réalisé de préférence par un <strong>médecin légiste</strong>. L'<strong>accord du mineur</strong> doit être respecté, et un refus est recevable même sur demande judiciaire.</p><ul><li>Chez la petite fille, il est réalisé en <strong>position de la grenouille</strong> (décubitus dorsal, jambes fléchies, plantes des pieds se touchant) avec l'éventuelle utilisation d'une sonde de Foley à ballonnet.</li><li>L'examen anal se fait dans la même position chez le petit enfant, et en décubitus dorsal avec jambes relevées chez l'adolescent.</li></ul>"},{"i":"a3e9e1eb2260","n":57,"o":"57-25","u":"Diagnostic positif / Examen C","t":"Maltraitance et enfants en danger : connaître les modalités de l’enquête clinique","q":"Quels sont les 3 scénarios typiques qui déclenchent la suspicion de maltraitance chez un enfant lors d'une consultation médicale ?","a":"<p>Les 3 circonstances diagnostiques de maltraitance sont :</p><ul><li>L'<strong>enfant qui révèle lui-même des violences</strong>, constituant le motif de la consultation.</li><li>L'<strong>enfant accompagné par un parent ou un tiers</strong> qui exprime une suspicion de violences, de négligences ou de mise en danger.</li><li>La <strong>présentation clinique du mineur</strong> (lésions cutanées/muqueuses, tableaux neurologiques, détresse psychique, IST, etc.) qui soulève la question de violences ou négligences.</li></ul>"},{"i":"cf42f36c2af2","n":57,"o":"57-25","u":"Diagnostic positif / Examen C","t":"Maltraitance et enfants en danger : connaître les modalités de l’enquête clinique","q":"Lors de l'examen clinique d'un enfant suspecté de maltraitance, quelle particularité de l'examen bucco-dentaire est le marqueur le plus pertinent de négligence ?","a":"<p>Un <strong>mauvais état bucco-dentaire</strong> (hygiène, caries non soignées) est le marqueur le plus pertinent de la négligence chez l'enfant.</p>"},{"i":"00d106d8a28d","n":57,"o":"57-26","u":"Prise en charge","t":"Maltraitance et enfants en danger : connaître les modalités de l’orientation médicale et administrative","q":"Dans quels cas un enfant doit-il être hospitalisé en UAPED dans le cadre d'une situation urgente de maltraitance ?","a":"<p>L'hospitalisation en UAPED est indiquée en cas de danger immédiat pour l'enfant, incluant notamment :</p><ul><li>Des <strong>lésions particulièrement graves</strong>.</li><li>Des violences sexuelles alléguées.</li><li>Des <strong>risques encourus au domicile</strong> compromettant la sécurité de l'enfant.</li><li>Une <strong>urgence médico-légale</strong> nécessitant des prélèvements (par exemple, pour des violences sexuelles de moins de 5 jours).</li><li>Un <strong>refus d'hospitalisation</strong> et une fugue des parents, nécessitant une protection urgente.</li></ul>"},{"i":"02b34bba81ba","n":57,"o":"57-26","u":"Prise en charge","t":"Maltraitance et enfants en danger : connaître les modalités de l’orientation médicale et administrative","q":"Quelle est la première étape décisionnelle face à une suspicion de maltraitance grave chez un enfant ?","a":"<p>Devant une suspicion de maltraitance grave, la première étape est de vérifier si la situation constitue une <strong>urgence avérée</strong>, en posant notamment les questions clés suivantes :</p><ul><li>Y a-t-il un refus de soins urgents ?</li><li>Y a-t-il une nécessité de protection urgente ?</li><li>Un constat médico-légal urgent est-il requis (ex: infraction sexuelle de moins de 5 jours) ?</li></ul>"},{"i":"2a9891f273c8","n":57,"o":"57-26","u":"Prise en charge","t":"Maltraitance et enfants en danger : connaître les modalités de l’orientation médicale et administrative","q":"Comment doit-on agir face à une situation de maltraitance non urgente ?","a":"<p>En dehors d'une urgence, il est primordial de <strong>caractériser le danger et les risques encourus</strong>. Ensuite, l'action à mener est soit :</p><ul><li>Une <strong>Information Préoccupante (IP)</strong>, transmise à la Cellule de Recueil des Informations Préoccupantes (CRIP), en cas de risque de danger, maltraitance ou négligence.</li><li>Un <strong>Signalement Judiciaire</strong>, directement au Procureur, face à un danger avéré et immédiat.</li></ul><p>Il est aussi conseillé de solliciter l'avis du <strong>médecin référent protection de l'enfance du Conseil départemental</strong> ou du <strong>service hospitalier référent UAPED</strong>.</p>"},{"i":"3cc0d7a02253","n":57,"o":"57-26","u":"Prise en charge","t":"Maltraitance et enfants en danger : connaître les modalités de l’orientation médicale et administrative","q":"Quelles sont les modalités d'orientation pour une situation de maltraitance grave jugée urgente ?","a":"<p>Pour une situation de maltraitance grave et urgente, l'orientation doit être <strong>immédiate</strong> et implique deux actions principales :</p><ul><li>Un <strong>signalement judiciaire</strong> au Procureur (par téléphone puis par écrit) ou, à défaut, au commissariat/gendarmerie.</li><li>Une <strong>prise en charge hospitalière</strong> en Unité d’Accueil Pédiatrique Enfant en Danger (UAPED).</li></ul>"},{"i":"a1a67d61c2d6","n":57,"o":"57-26","u":"Prise en charge","t":"Maltraitance et enfants en danger : connaître les modalités de l’orientation médicale et administrative","q":"Qu'est-ce qu'une Unité d’Accueil Pédiatrique Enfant en Danger (UAPED) ?","a":"<p>Les Unités d’Accueil Pédiatrique Enfant en Danger (UAPED) sont des services hospitaliers <strong>référents</strong> regroupant des <strong>équipes pluridisciplinaires</strong>. Elles ont pour rôle le <strong>repérage</strong> et le <strong>diagnostic</strong> des situations de maltraitance, ainsi que la <strong>coordination des soins</strong>. Elles sont une « clé de voûte » hospitalière et tout professionnel confronté à une situation de maltraitance peut les contacter.</p>"},{"i":"3ac9e46c447d","n":57,"o":"57-27","u":"Prise en charge","t":"Maltraitance et enfants en danger : connaître les modalités de la prise en charge médicale","q":"Quelles sont les mesures spécifiques à prendre en cas de violences sexuelles chez un enfant ?","a":"<p>En cas de violences sexuelles, les mesures sont :</p><ul><li>La <strong>contraception d'urgence</strong> : si l'âge le permet et si le rapport a eu lieu il y a <strong>moins de 120 heures</strong>.</li><li>Le <strong>traitement antirétroviral</strong> : discussion selon la nature de l'agression et le délai entre l'agression et la consultation.</li><li>Le <strong>dépistage et le suivi des IST</strong>.</li></ul>"},{"i":"47644f02bb5b","n":57,"o":"57-27","u":"Prise en charge","t":"Maltraitance et enfants en danger : connaître les modalités de la prise en charge médicale","q":"Quelle est la prise en charge immédiate des traumatismes infligés chez un enfant en situation de maltraitance ?","a":"<p>La prise en charge immédiate inclut :</p><ul><li>La <strong>cotation de la douleur</strong> et sa prise en charge thérapeutique.</li><li>Pour les <strong>lésions neurologiques</strong> : discussion d'un transfert en milieu neurochirurgical.</li><li>Pour les <strong>lésions orthopédiques</strong> : avis orthopédique sur site.</li><li>Pour les <strong>lésions tégumentaires</strong> : soins des plaies/brûlures et administration d'un <strong>SAT-VAT</strong> (sérum antitétanique + vaccination si non à jour).</li></ul>"},{"i":"ce34e9b50078","n":57,"o":"57-27","u":"Prise en charge","t":"Maltraitance et enfants en danger : connaître les modalités de la prise en charge médicale","q":"Comment dépister les IST et assurer le soutien/coordination après des violences sexuelles chez un enfant ?","a":"<p>Le dépistage des IST comprend :</p><ul><li>Un bilan initial : recherche de <strong>Gonocoque</strong>, <strong>Chlamydia</strong> (urines, écouvillons vaginal/rectal/pharyngé), et sérologies <strong>VIH</strong>, <strong>syphilis</strong>, <strong>VHB</strong>, <strong>VHC</strong> (avec recherche possible de mycoplasme, trichomonas selon le contexte).</li><li>Le bilan est à renouveler à <strong>6 semaines</strong> puis à <strong>3 mois</strong>.</li><li>Une recherche de grossesse par <strong>β-hCG urinaire et plasmatique</strong> est réalisée selon la puberté de l'enfant.</li></ul><p>Le soutien et la coordination incluent :</p><ul><li>Un <strong>soutien médico-psychologique</strong> pour l'enfant et sa famille.</li><li>L'organisation des soins d'aval et la <strong>coordination assurée par les UAPED</strong> (Unités d'Accueil Pédiatrique Enfants en Danger, généralisation prévue dans tous les hôpitaux).</li></ul>"},{"i":"354dc96176cd","n":57,"o":"57-29","u":"Étiologie","t":"Maltraitance et enfants en danger : savoir évoquer le diagnostic d’abus sexuel","q":"Quels paramètres recueillir lors de l'entretien avec un mineur suite à une suspicion de violences sexuelles ?","a":"<p>Les données à recueillir sont :</p><ul><li>Les <strong>révélations</strong>, leurs conditions, la présence de tiers, le délai depuis les faits, et si le contact persiste avec l'auteur.</li><li>L'évaluation de l'asthénie, des idées noires, du sommeil/alimentation, de la scolarité, des rapports avec les pairs et la famille.</li><li>Le statut de propreté, la présence de troubles du comportement ou de jeux sexuels.</li><li>Chez les adolescents, l'ajout de questions sur les toxiques, la contraception, le stade pubertaire, la date des règles et les rapports sexuels antérieurs/postérieurs.</li><li>La consultation du <strong>carnet de santé</strong> pour les antécédents et les courbes de croissance.</li></ul>"},{"i":"47676214c1c9","n":57,"o":"57-29","u":"Étiologie","t":"Maltraitance et enfants en danger : savoir évoquer le diagnostic d’abus sexuel","q":"Quels sont les signes d'alerte spécifiques aux adolescents en cas de violences sexuelles subies ?","a":"<p>Chez l'adolescent, les signes d'alerte peuvent inclure :</p><ul><li>Une <strong>auto-agressivité</strong> (scarifications, restriction alimentaire, dévalorisation, idées ou tentatives de suicide).</li><li>Une <strong>hétéro-agressivité</strong> (violences agies) qui peut évoquer des violences subies.</li></ul>"},{"i":"5a7cad001fd9","n":57,"o":"57-29","u":"Étiologie","t":"Maltraitance et enfants en danger : savoir évoquer le diagnostic d’abus sexuel","q":"Quelles sont les circonstances devant faire évoquer le diagnostic de violences sexuelles chez un enfant ?","a":"<ul><li>L'enfant <strong>révèle spontanément des faits de nature sexuelle</strong> (les fausses allégations spontanées sont très rares).</li><li>L'enfant présente des <strong>anomalies à l'examen périnéal</strong>.</li><li>L'entourage suspecte des faits devant des <strong>troubles du comportement</strong>, des <strong>conflits familiaux</strong> ou des <strong>révélations après questionnements</strong> (qui doivent être menés avec prudence).</li><li>L'enfant présente des signes fonctionnels non spécifiques comme une énurésie, une encoprésie, des douleurs abdominales, des céphalées ou des troubles du comportement alimentaire (TCA).</li></ul>"},{"i":"5e1cea825d05","n":57,"o":"57-29","u":"Étiologie","t":"Maltraitance et enfants en danger : savoir évoquer le diagnostic d’abus sexuel","q":"Quel bilan biologique réaliser en cas de suspicion de violences sexuelles chez un enfant ou un adolescent ?","a":"<p>Le bilan biologique recommandé est le suivant :</p><ul><li><strong>β-hCG</strong> urinaire et plasmatique (selon la puberté).</li><li>Bilan de <strong>détection d'IST</strong> (Infections Sexuellement Transmissibles) : <strong>gonocoque</strong>, <strong>chlamydia</strong> (sur urines, écouvillons vaginal/rectal/pharyngé), <strong>sérologies VIH 1 et 2</strong>, <strong>syphilis</strong>, <strong>VHB</strong>, <strong>VHC</strong>. Des recherches de mycoplasme et trichomonas peuvent être ajoutées au cas par cas.</li><li>Les sérologies IST sont à <strong>renouveler à 6 semaines puis à 3 mois</strong>.</li><li>Un <strong>screening toxicologique</strong> (sang, urines, cheveux) peut être réalisé au cas par cas.</li></ul>"},{"i":"69b88314acb1","n":57,"o":"57-29","u":"Étiologie","t":"Maltraitance et enfants en danger : savoir évoquer le diagnostic d’abus sexuel","q":"Comment doit être mené l'entretien avec un mineur lors de la suspicion de violences sexuelles ?","a":"<p>L'entretien doit être mené de la manière suivante :</p><ul><li>Le mineur doit être <strong>seul ou accompagné selon ses souhaits</strong>.</li><li>Poser uniquement des <strong>questions ouvertes</strong> comme « raconte-moi » ou « dis-moi en plus », en utilisant un vocabulaire adapté à l'âge.</li><li>Il est crucial de <strong>ne pas utiliser de questions fermées ou suggestives</strong> afin de ne pas polluer la mémoire de l'enfant.</li></ul>"},{"i":"dca9796382df","n":57,"o":"57-29","u":"Étiologie","t":"Maltraitance et enfants en danger : savoir évoquer le diagnostic d’abus sexuel","q":"Quand faut-il référer en urgence un mineur victime de violences sexuelles à une équipe spécialisée (UAPED) ?","a":"<p>Une prise en charge urgente par une équipe spécialisée (UAPED) est nécessaire dans les situations suivantes :</p><ul><li><strong>Nécessité de soins immédiats</strong> (prophylaxie post-exposition au <strong>VIH</strong> - ARV, interventions chirurgicales, soins pédopsychiatriques urgents).</li><li>Nécessité d'assurer une <strong>protection vis-à-vis de l'auteur présumé</strong>.</li><li>Urgence <strong>médico-judiciaire</strong>, notamment pour la réalisation de prélèvements et la constatation de lésions traumatiques, classiquement dans un délai de <strong>moins de 5 jours</strong> après les faits.</li></ul>"},{"i":"e0b4df4031b2","n":57,"o":"57-29","u":"Étiologie","t":"Maltraitance et enfants en danger : savoir évoquer le diagnostic d’abus sexuel","q":"Quelle terminologie privilégier en France pour évoquer un abus sexuel chez un enfant ?","a":"<p>En France, il est recommandé d'utiliser le terme de <strong>violences sexuelles</strong>. Ce terme est préféré même si ces violences sont le plus souvent commises sans violence physique ou verbale, mais plutôt par intimidation, séduction ou abus d'autorité.</p>"},{"i":"0a30d5276928","n":57,"o":"57-30","u":"Définition","t":"Connaître les institutions de prise en charge : Protection maternelle et infantile","q":"Pour quelle tranche d'âge d'enfants la Protection Maternelle et Infantile (PMI) assure-t-elle le suivi ?","a":"<p>La Protection Maternelle et Infantile (PMI) concerne les enfants de <strong>moins de 6 ans</strong>.</p>"},{"i":"1bb1a4905cbe","n":57,"o":"57-30","u":"Définition","t":"Connaître les institutions de prise en charge : Protection maternelle et infantile","q":"Quels professionnels composent l'équipe pluridisciplinaire d'un service de Protection Maternelle et Infantile (PMI) ?","a":"<p>L'équipe pluridisciplinaire de la PMI est coordonnée par un médecin et comprend :</p><ul><li>Des <strong>médecins</strong> (pédiatres, généralistes, gynécologues)</li><li>Des <strong>sages-femmes</strong> et des <strong>puéricultrices</strong> (rôles prépondérants)</li><li>Des assistantes sociales</li><li>Des éducateurs</li><li>Des psychologues</li><li>Des kinésithérapeutes</li></ul>"},{"i":"6bac65ad9f5a","n":57,"o":"57-30","u":"Définition","t":"Connaître les institutions de prise en charge : Protection maternelle et infantile","q":"Quelle est la définition de la Protection Maternelle et Infantile (PMI) ?","a":"<p>La Protection Maternelle et Infantile (PMI) est un <strong>service départemental</strong> ayant comme mission principale d'assurer la <strong>protection sanitaire de la mère et de l'enfant</strong>. Elle joue un rôle majeur dans le repérage de la maltraitance.</p>"},{"i":"7f8e72f5ee4c","n":57,"o":"57-30","u":"Définition","t":"Connaître les institutions de prise en charge : Protection maternelle et infantile","q":"À quelle autorité la Protection Maternelle et Infantile (PMI) est-elle rattachée ?","a":"<p>La Protection Maternelle et Infantile (PMI) est placée sous la responsabilité du <strong>président du Conseil départemental</strong>.</p>"},{"i":"83c141ac1137","n":57,"o":"57-30","u":"Définition","t":"Connaître les institutions de prise en charge : Protection maternelle et infantile","q":"Quelles sont les missions principales de la Protection Maternelle et Infantile (PMI) ?","a":"<p>Les missions principales de la Protection Maternelle et Infantile (PMI) sont :</p><ul><li>Des <strong>consultations et visites à domicile gratuites</strong> pour les familles, nourrissons et femmes enceintes.</li><li>Des mesures de <strong>prévention</strong> (médicale, psychologique, sociale, éducation à la santé).</li><li>Des actions de <strong>dépistage</strong>, incluant les situations de maltraitance.</li><li>La prise en charge des <strong>handicaps de l'enfant de moins de 6 ans</strong> (orientation vers des structures adaptées).</li><li>Le <strong>contrôle des établissements et services d'accueil d'enfants de moins de 6 ans</strong>, ainsi que des assistantes maternelles.</li><li>La <strong>surveillance médicale préventive à l'école maternelle</strong>.</li><li>Des actions de <strong>santé publique et de surveillance épidémiologique</strong> (avis de naissance, certificats de santé obligatoires à <strong>8 jours, 9 mois, 24 mois</strong>).</li><li>Un <strong>rôle éducatif</strong> auprès des familles, particulièrement celles en difficulté.</li></ul>"},{"i":"171e11fddebb","n":57,"o":"57-4","u":"Diagnostic positif","t":"Nourrisson : savoir évoquer un syndrome du bébé secoué et connaître la conduite diagnostique","q":"Quels sont les signes cliniques digestifs et neurologiques pouvant faire évoquer un syndrome du bébé secoué chez le nourrisson ?","a":"<p>Les signes cliniques évocateurs du syndrome du bébé secoué comprennent :</p><ul><li>Sur le plan digestif : des <strong>vomissements</strong>, généralement sans diarrhée, ce qui le distingue d'une gastro-entérite aiguë.</li><li>Sur le plan neurologique : un <strong>bombement de la fontanelle antérieure</strong>, des <strong>convulsions</strong>, une <strong>hypotonie axiale</strong>, des <strong>troubles de la vigilance</strong>, un <strong>arrêt des acquisitions</strong> ou une <strong>régression psychomotrice</strong>, et un <strong>changement de couloir</strong> de la courbe du périmètre crânien.</li></ul>"},{"i":"399cf75bc8eb","n":57,"o":"57-4","u":"Diagnostic positif","t":"Nourrisson : savoir évoquer un syndrome du bébé secoué et connaître la conduite diagnostique","q":"Quels sont les signes cliniques généraux pouvant faire évoquer un syndrome du bébé secoué chez le nourrisson ?","a":"<p>Les signes généraux évocateurs du syndrome du bébé secoué incluent :</p><ul><li>Une <strong>pâleur</strong>.</li><li>Un <strong>malaise grave</strong>.</li><li>Des <strong>pauses respiratoires</strong>.</li><li>Une <strong>irritabilité</strong> marquée.</li></ul>"},{"i":"5b73c21ad1db","n":57,"o":"57-4","u":"Diagnostic positif","t":"Nourrisson : savoir évoquer un syndrome du bébé secoué et connaître la conduite diagnostique","q":"Quelle est la conduite diagnostique initiale en cas de suspicion de syndrome du bébé secoué chez un nourrisson ?","a":"<p>Toute suspicion de syndrome du bébé secoué (SBS) impose une <strong>hospitalisation en urgence</strong> du nourrisson pour un <strong>bilan paraclinique exhaustif</strong> et sa <strong>mise à l'abri</strong>.</p>"},{"i":"83a1ecb440e5","n":57,"o":"57-4","u":"Diagnostic positif","t":"Nourrisson : savoir évoquer un syndrome du bébé secoué et connaître la conduite diagnostique","q":"Quels examens d'imagerie cérébrale et osseuse sont systématiquement réalisés dans le bilan paraclinique d'un syndrome du bébé secoué chez un enfant de moins de 2 ans ?","a":"<p>Le bilan paraclinique systématique chez un enfant de moins de 2 ans comprend :</p><ul><li>Une <strong>TDM cérébrale</strong> avec reconstruction 3D, descendant jusqu'en C6.</li><li>Une <strong>IRM cérébrale et médullaire</strong>, en complément ou en première intention en l'absence de symptômes neurologiques.</li><li>Un <strong>examen ophtalmologique</strong> avec fond d'œil réalisé dans les <strong>48 heures</strong> suivant le traumatisme, avec photos si anomalie.</li><li>Un <strong>bilan radiographique squelettique complet</strong> selon un protocole d'analyse segment par segment, relu par deux radiologues spécialisés en pédiatrie. En cas de bilan douteux ou forte suspicion, une <strong>scintigraphie osseuse</strong> ou une nouvelle radiographie de contrôle à 10 jours peut être réalisée.</li></ul>"},{"i":"9c4f1d4ed6e4","n":57,"o":"57-4","u":"Diagnostic positif","t":"Nourrisson : savoir évoquer un syndrome du bébé secoué et connaître la conduite diagnostique","q":"Quel bilan biologique est réalisé en cas de suspicion de syndrome du bébé secoué ou d'hématome sous-dural (HSD) ?","a":"<p>Le bilan biologique comprend :</p><ul><li>Une <strong>NFS</strong>, un <strong>bilan d'hémostase complet</strong> et un <strong>ionogramme sanguin</strong>.</li><li>Un bilan du cuivre (cuprémie, cuprurie, céruléoplasmine) pour rechercher une <strong>maladie de Menkes</strong>.</li><li>Une chromatographie des acides organiques urinaires pour rechercher une <strong>acidurie glutarique de type 1</strong> (déficit en glutaryl-CoA déshydrogénase).</li></ul>"},{"i":"179cf713e9c0","n":57,"o":"57-5","u":"Diagnostic positif","t":"Nourrisson : connaître les lésions associées au syndrome du bébé secoué","q":"Quelles sont les lésions intracrâniennes caractéristiques du syndrome du bébé secoué (SBS) ?","a":"<p>Les lésions intracrâniennes caractéristiques du SBS incluent :</p><ul><li>Un <strong>hématome sous-dural (HSD)</strong>, souvent hyperdense, en croissant, situé à la convexité, et considéré comme la lésion-clé du SBS.</li><li>Une hémorragie sous-arachnoïdienne (HSA) associée.</li><li>Un œdème cérébral.</li><li>Des lésions hypoxo-anoxiques (hypodensités de la substance blanche, du cortex ou des noyaux gris).</li><li>Des fractures cranio-faciales.</li></ul>"},{"i":"9f63410d516b","n":57,"o":"57-5","u":"Diagnostic positif","t":"Nourrisson : connaître les lésions associées au syndrome du bébé secoué","q":"Quelles sont les lésions ophtalmologiques associées au syndrome du bébé secoué (SBS) ?","a":"<p>Les lésions ophtalmologiques associées au SBS sont :</p><ul><li>Des <strong>hémorragies rétiniennes</strong> dans environ <strong>80 % des cas</strong>. Elles sont quasi-pathognomoniques si elles sont multiples, diffuses ou s'étendent jusqu'à la périphérie de la rétine.</li><li>Un œdème papillaire si une hypertension intracrânienne (HTIC) est présente.</li><li>Une hémorragie du vitré.</li></ul><p>Il est important de noter que les hémorragies rétiniennes ne sont pas absolument pathognomoniques, car elles peuvent également être observées après un accident de la voie publique (AVP) ou un accouchement difficile chez le nouveau-né.</p>"},{"i":"d6400c19eeec","n":57,"o":"57-5","u":"Diagnostic positif","t":"Nourrisson : connaître les lésions associées au syndrome du bébé secoué","q":"Quelles sont les autres lésions (médullaires, associées) fréquemment rencontrées dans le syndrome du bébé secoué (SBS) ?","a":"<p>Les autres lésions fréquemment rencontrées sont :</p><p><strong>Lésions médullaires :</strong></p><ul><li>Des lésions du rachis cervical, justifiant une imagerie jusqu'en C6.</li></ul><p><strong>Lésions associées :</strong></p><ul><li>Des <strong>lésions tégumentaires sentinelles</strong> (ecchymoses, hématomes).</li><li>Des lésions ORL intrabuccales.</li><li>Des <strong>fractures</strong> (notamment des côtes – arcs postérieurs/moyens – et des fractures métaphysaires ou crâniennes).</li><li>Des lésions viscérales abdominales.</li><li>Des signes d'intoxications ou de violences sexuelles associées.</li></ul>"},{"i":"e016d3d01638","n":57,"o":"57-5","u":"Diagnostic positif","t":"Nourrisson : connaître les lésions associées au syndrome du bébé secoué","q":"Quelle est la triade-clé diagnostique du syndrome du bébé secoué (SBS) ?","a":"<p>Le <strong>syndrome du bébé secoué (SBS)</strong> est caractérisé par la triade-clé suivante, constituant sa signature radio-clinique :</p><ul><li>Un <strong>hématome sous-dural (HSD) de la convexité</strong>.</li><li>Des <strong>hémorragies rétiniennes multiples</strong>.</li><li>Des <strong>lésions hypoxo-anoxiques</strong>.</li></ul><p>Cette triade doit être systématiquement complétée par la recherche de lésions sentinelles (téguments, fractures, sphère ORL).</p>"},{"i":"9cfc7cd73b00","n":57,"o":"57-9","u":"Étiologie","t":"Nourrisson : connaître les diagnostics différentiels et mécanismes lésionnels à éliminer (SBS)","q":"Quelle est la règle d'or pédiatrique concernant la suspicion de Syndrome du Bébé Secoué chez le nourrisson ?","a":"<p>Toute hémorragie sous-durale (HSD) ou hémorragie rétinienne chez un nourrisson, en l'absence de cinétique élevée connue et prouvée, doit être considérée comme un <strong>Syndrome du Bébé Secoué (SBS) jusqu'à preuve du contraire</strong>. Les diagnostics différentiels doivent être formellement éliminés par un bilan exhaustif et ne doivent jamais être présumés.</p>"},{"i":"aff29524b277","n":57,"o":"57-9","u":"Étiologie","t":"Nourrisson : connaître les diagnostics différentiels et mécanismes lésionnels à éliminer (SBS)","q":"Comment distinguer un traumatisme crânien accidentel avec cinétique faible (< 1,5m) d'un Syndrome du Bébé Secoué chez un nourrisson ?","a":"<p>Un traumatisme crânien accidentel résultant d'une chute de <strong>moins de 1,5 mètre ne peut pas causer d'hémorragie sous-durale (HSD) ni d'hémorragies rétiniennes</strong>. Un diagnostic de traumatisme crânien accidentel est retenu si les circonstances sont connues, non changeantes, décrites de manière similaire par les témoins, et si la cinétique est supérieure à 1,5 mètre.</p>"},{"i":"d3a5f2245819","n":57,"o":"57-9","u":"Étiologie","t":"Nourrisson : connaître les diagnostics différentiels et mécanismes lésionnels à éliminer (SBS)","q":"Quelles sont les caractéristiques cliniques et les éléments diagnostiques clés de l'acidurie glutarique de type 1, un diagnostic différentiel du Syndrome du Bébé Secoué ?","a":"<p>L'acidurie glutarique de type 1 se manifeste souvent par une <strong>crise encéphalopathique aiguë initiale entre 3 et 36 mois</strong>, avec <strong>hypotonie</strong>, perte des capacités motrices et convulsions. L'imagerie cérébrale peut montrer une <strong>lésion striatale bilatérale</strong>, parfois associée à des hémorragies rétiniennes et sous-durales. Le diagnostic est confirmé par la <strong>chromatographie des acides organiques urinaires</strong>.</p>"},{"i":"eb1598583fa0","n":57,"o":"57-9","u":"Étiologie","t":"Nourrisson : connaître les diagnostics différentiels et mécanismes lésionnels à éliminer (SBS)","q":"Quelles sont les caractéristiques cliniques et les éléments diagnostiques clés de la maladie de Menkes, un diagnostic différentiel du Syndrome du Bébé Secoué ?","a":"<p>La maladie de Menkes est une maladie congénitale rare du métabolisme du cuivre. Dès les premiers mois de vie, elle peut entraîner des <strong>fractures spontanées</strong> et des <strong>céphalohématomes</strong>, puis évolue vers un retard de croissance, des difficultés d'alimentation et une détérioration motrice (hypotonie puis spasticité). Le diagnostic est posé par le dosage de la <strong>cuprémie, cuprurie et céruléoplasmine</strong>.</p>"}]};